INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-1', 'Whatever our souls are made of, his and mine are the same.', 'Emily Brontë', 'Romance', '["soul", "love", "passion"]', 'midnight', 0, 116),
('quote-2', 'You have bewitched me, body and soul, and I love, I love, I love you.', 'Jane Austen', 'Romance', '["devotion", "passion", "romance"]', 'nordic', 0, 49),
('quote-3', 'I loved her against reason, against promise, against peace, against hope, against happiness, against all discouragement that could be.', 'Charles Dickens', 'Romance', '["longing", "unconditional", "heart"]', 'sunset', 0, 38),
('quote-4', 'I love you without knowing how, or when, or from where. I love you straightforwardly, without complexities or pride.', 'Pablo Neruda', 'Romance', '["devotion", "poetry", "eternal"]', 'light', 0, 129),
('quote-5', 'Love recognizes no barriers. It jumps hurdles, leaps fences, penetrates walls to arrive at its destination full of hope.', 'Maya Angelou', 'Romance', '["barrier", "hope", "strength"]', 'emerald', 0, 70),
('quote-6', 'Lovers don''t finally meet somewhere. They''re in each other all along.', 'Rumi', 'Romance', '["destiny", "spiritual", "connection"]', 'midnight', 0, 66),
('quote-7', 'If I had a flower for every time I thought of you... I could walk through my garden forever.', 'Alfred Tennyson', 'Romance', '["affection", "memory", "garden"]', 'nordic', 0, 63),
('quote-8', 'In vain have I struggled. It will not do. My feelings will not be repressed. You must allow me to tell you how ardently I admire and love you.', 'Jane Austen', 'Romance', '["confession", "ardor", "pride"]', 'sunset', 0, 52),
('quote-9', 'The best thing to hold onto in life is each other.', 'Audrey Hepburn', 'Romance', '["togetherness", "tenderness", "life"]', 'light', 0, 129),
('quote-10', 'Grow old along with me! The best is yet to be.', 'Robert Browning', 'Romance', '["aging", "companionship", "future"]', 'emerald', 0, 48),
('quote-11', 'You are my heart, my life, my one and only thought.', 'Arthur Conan Doyle', 'Romance', '["devotion", "clarity", "loyalty"]', 'midnight', 0, 121),
('quote-12', 'When you realize you want to spend the rest of your life with somebody, you want the rest of your life to start as soon as possible.', 'Nora Ephron', 'Romance', '["commitment", "romance", "future"]', 'nordic', 0, 129),
('quote-13', 'To love and be loved is to feel the sun from both sides.', 'David Viscott', 'Romance', '["warmth", "harmony", "joy"]', 'sunset', 0, 104),
('quote-14', 'I would rather spend one lifetime with you, than face all the ages of this world alone.', 'J.R.R. Tolkien', 'Romance', '["eternity", "loyalty", "companionship"]', 'light', 0, 46),
('quote-15', 'We loved with a love that was more than love.', 'Edgar Allan Poe', 'Romance', '["passion", "intense", "timeless"]', 'emerald', 0, 110),
('quote-16', 'Love is composed of a single soul inhabiting two bodies.', 'Aristotle', 'Romance', '["unity", "philosophy", "soul"]', 'midnight', 0, 89),
('quote-17', 'If you remember me, then I don''t care if everyone else forgets.', 'Haruki Murakami', 'Romance', '["devotion", "memory", "intimacy"]', 'nordic', 0, 39),
('quote-18', 'There is no charm equal to tenderness of heart.', 'Jane Austen', 'Romance', '["gentleness", "charm", "tenderness"]', 'sunset', 0, 38),
('quote-19', 'I wish you to know that you have been the last dream of my soul.', 'Charles Dickens', 'Romance', '["dream", "soul", "devotion"]', 'light', 0, 46),
('quote-20', 'Doubt thou the stars are fire; Doubt that the sun doth move; Doubt truth to be a liar; But never doubt I love.', 'William Shakespeare', 'Romance', '["faith", "certainty", "classic"]', 'emerald', 0, 62),
('quote-21', 'If I know what love is, it is because of you.', 'Hermann Hesse', 'Romance', '["awakening", "gratitude", "deep"]', 'midnight', 0, 64),
('quote-22', 'Love is an untamed force. When we try to control it, it destroys us. When we try to imprison it, it enslaves us. When we try to understand it, it leaves us feeling lost and confused.', 'Paulo Coelho', 'Romance', '["nature", "wild", "surrender"]', 'nordic', 0, 99),
('quote-23', 'You don''t love someone because they''re perfect, you love them in spite of the fact that they''re not.', 'Jodi Picoult', 'Romance', '["acceptance", "grace", "authenticity"]', 'sunset', 0, 112),
('quote-24', 'Where there is love there is life.', 'Mahatma Gandhi', 'Romance', '["vitality", "truth", "living"]', 'light', 0, 38),
('quote-25', 'I look at you and I would rather look at you than all the portraits in the world.', 'Frank O''Hara', 'Romance', '["beauty", "gaze", "modern"]', 'emerald', 0, 106),
('quote-26', 'My heart is, and always will be, yours.', 'Jane Austen', 'Romance', '["constancy", "loyalty", "gift"]', 'midnight', 0, 60),
('quote-27', 'The minute I heard my first love story I started looking for you, not knowing how blind that was.', 'Rumi', 'Romance', '["searching", "destiny", "awakening"]', 'nordic', 0, 126),
('quote-28', 'Love does not consist in gazing at each other, but in looking outward together in the same direction.', 'Antoine de Saint-Exupéry', 'Romance', '["partnership", "journey", "shared-vision"]', 'sunset', 0, 118),
('quote-29', 'I am who I am because of you. You are every reason, every hope, and every dream I''ve ever had.', 'Nicholas Sparks', 'Romance', '["gratitude", "inspiration", "romantic"]', 'light', 0, 124),
('quote-30', 'To love or have loved, that is enough. Ask nothing further. There is no other pearl to be found in the dark folds of life.', 'Victor Hugo', 'Romance', '["completeness", "pearl", "treasure"]', 'emerald', 0, 104),
('quote-31', 'You are part of my existence, part of myself. You have been in every line I have ever read.', 'Charles Dickens', 'Romance', '["presence", "literature", "woven"]', 'midnight', 0, 88),
('quote-32', 'Soul meets soul on lovers'' lips.', 'Percy Bysshe Shelley', 'Romance', '["kiss", "soul", "poetry"]', 'nordic', 0, 63),
('quote-33', 'I have waited for this opportunity for more than half a century, to repeat to you once again my vow of eternal fidelity and everlasting love.', 'Gabriel García Márquez', 'Romance', '["patience", "eternity", "loyalty"]', 'sunset', 0, 92),
('quote-34', 'If equal affection cannot be, let the more loving one be me.', 'W.H. Auden', 'Romance', '["generosity", "vulnerability", "poetic"]', 'light', 0, 110),
('quote-35', 'You pierce my soul. I am half agony, half hope.', 'Jane Austen', 'Romance', '["longing", "hope", "vulnerability"]', 'emerald', 0, 70),
('quote-36', 'There is no remedy for love but to love more.', 'Henry David Thoreau', 'Romance', '["healing", "limitless", "cure"]', 'midnight', 0, 138),
('quote-37', 'I fell in love the way you fall asleep: slowly, and then all at once.', 'John Green', 'Romance', '["surrender", "unfolding", "spark"]', 'nordic', 0, 35),
('quote-38', 'One word frees us of all the weight and pain of life: that word is love.', 'Sophocles', 'Romance', '["freedom", "weightlessness", "ancient"]', 'sunset', 0, 132),
('quote-39', 'The heart has its reasons of which reason knows nothing.', 'Blaise Pascal', 'Romance', '["mystery", "intuition", "heart"]', 'light', 0, 138),
('quote-40', 'Take my hand, take my whole life too, for I can''t help falling in love with you.', 'Elvis Presley', 'Romance', '["surrender", "melody", "sweet"]', 'emerald', 0, 55),
('quote-41', 'I want to do with you what spring does with the cherry trees.', 'Pablo Neruda', 'Romance', '["rebirth", "nature", "blossom"]', 'midnight', 0, 124),
('quote-42', 'Your love shines in my heart as the sun that shines upon the earth.', 'Eleanor Di Guillo', 'Romance', '["sunlight", "warmth", "radiance"]', 'nordic', 0, 89),
('quote-43', 'You are my today and all of my tomorrows.', 'Leo Christopher', 'Romance', '["constancy", "present", "future"]', 'sunset', 0, 78),
('quote-44', 'A kiss is a lovely trick designed by nature to stop speech when words become superfluous.', 'Ingrid Bergman', 'Romance', '["kiss", "magic", "silence"]', 'light', 0, 70),
('quote-45', 'We are most alive when we''re in love.', 'John Updike', 'Romance', '["aliveness", "vitality", "spark"]', 'emerald', 0, 54),
('quote-46', 'For the two of us, home isn''t a place. It is a person. And we are finally home.', 'Stephanie Perkins', 'Romance', '["home", "sanctuary", "belonging"]', 'midnight', 0, 62),
('quote-47', 'Love is the bridge between two hearts.', 'Kahlil Gibran', 'Romance', '["bridge", "connection", "harmony"]', 'nordic', 0, 132),
('quote-48', 'You make me want to be a better man.', 'Mark Andrus', 'Romance', '["growth", "devotion", "betterment"]', 'sunset', 0, 78),
('quote-49', 'I knew the second I met you that there was something about you I needed. Turns out it wasn''t something about you at all. It was just you.', 'Jamie McGuire', 'Romance', '["epiphany", "clarity", "destiny"]', 'light', 0, 48),
('quote-50', 'Love is like the wind, you can''t see it but you can feel it.', 'Nicholas Sparks', 'Romance', '["invisible", "feeling", "gentle"]', 'emerald', 0, 46),
('quote-51', 'I desire to be with you. I think of you, I feel for you, I have no life without you.', 'Lord Byron', 'Romance', '["desire", "longing", "passion"]', 'midnight', 0, 83),
('quote-52', 'To love another person is to see the face of God.', 'Victor Hugo', 'Romance', '["sacred", "transcendence", "divine"]', 'nordic', 0, 47),
('quote-53', 'I never had a moment''s doubt. I loved you. I believe in you completely. You are my dearest one. My reason for life.', 'Ian McEwan', 'Romance', '["certainty", "faith", "dearest"]', 'sunset', 0, 80),
('quote-54', 'I have found the one whom my soul loves.', 'Song of Solomon', 'Romance', '["scripture", "sacred", "found"]', 'light', 0, 79),
('quote-55', 'Each time you happen to me all over again.', 'Edith Wharton', 'Romance', '["fresh", "wonder", "renewed"]', 'emerald', 0, 112),
('quote-56', 'Love takes off masks that we fear we cannot live without and know we cannot live within.', 'James Baldwin', 'Romance', '["authenticity", "vulnerability", "courage"]', 'midnight', 0, 68),
('quote-57', 'If you love somebody, let them go, for if they return, they were always yours. And if they don''t, they never were.', 'Kahlil Gibran', 'Romance', '["freedom", "trust", "letting-go"]', 'nordic', 0, 138),
('quote-58', 'Love is a canvas furnished by nature and embroidered by imagination.', 'Voltaire', 'Romance', '["canvas", "imagination", "art"]', 'sunset', 0, 40),
('quote-59', 'Being deeply loved by someone gives you strength, while loving someone deeply gives you courage.', 'Lao Tzu', 'Romance', '["strength", "courage", "depth"]', 'light', 0, 128),
('quote-60', 'Two souls with but a single thought, two hearts that beat as one.', 'John Keats', 'Romance', '["harmony", "rhythm", "unity"]', 'emerald', 0, 93),
('quote-61', 'There is only one happiness in this life, to love and be loved.', 'George Sand', 'Romance', '["happiness", "simplicity", "core"]', 'midnight', 0, 103),
('quote-62', 'My bounty is as boundless as the sea, my love as deep; the more I give to thee, the more I have, for both are infinite.', 'William Shakespeare', 'Romance', '["boundless", "infinite", "generosity"]', 'nordic', 0, 50),
('quote-63', 'Love looks not with the eyes, but with the mind; and therefore is winged Cupid painted blind.', 'William Shakespeare', 'Romance', '["mind", "vision", "depth"]', 'sunset', 0, 83),
('quote-64', 'Love isn''t something natural. Rather it requires discipline, concentration, patience, faith, and the overcoming of narcissism.', 'Erich Fromm', 'Romance', '["discipline", "growth", "wisdom"]', 'light', 0, 45),
('quote-65', 'They slipped briskly into an intimacy from which they never recovered.', 'F. Scott Fitzgerald', 'Romance', '["intimacy", "connection", "grace"]', 'emerald', 0, 105),
('quote-66', 'I loved you yesterday, love you still, always have, always will.', 'Elaine Davis', 'Romance', '["unending", "time", "steadfast"]', 'midnight', 0, 72),
('quote-67', 'I cannot fix on the hour, or the spot, or the look or the words, which laid the foundation. It was too long ago. I was in the middle before I knew that I had begun.', 'Jane Austen', 'Romance', '["origins", "inevitable", "gentle"]', 'nordic', 0, 115),
('quote-68', 'You are every breath I take, every step I make.', 'Nicholas Sparks', 'Romance', '["breath", "rhythm", "presence"]', 'sunset', 0, 114),
('quote-69', 'The water shines only by the sun. And it is you who are my sun.', 'Charles de Leusse', 'Romance', '["sunshine", "reflection", "light"]', 'light', 0, 81),
('quote-70', 'Love is a friendship that has caught fire.', 'Ann Landers', 'Romance', '["friendship", "warmth", "flame"]', 'emerald', 0, 108),
('quote-71', 'In all the world, there is no heart for me like yours. In all the world, there is no love for you like mine.', 'Maya Angelou', 'Romance', '["uniqueness", "reciprocity", "match"]', 'midnight', 0, 59),
('quote-72', 'Whatever is done for love always occurs beyond good and evil.', 'Friedrich Nietzsche', 'Romance', '["beyond", "transcendence", "depth"]', 'nordic', 0, 125),
('quote-73', 'To be your friend was all I ever wanted; to be your lover was all I ever dreamed.', 'Valerie Lombardo', 'Romance', '["friendship", "dream", "fulfillment"]', 'sunset', 0, 43),
('quote-74', 'I love you more than my own skin.', 'Frida Kahlo', 'Romance', '["passion", "art", "raw"]', 'light', 0, 40),
('quote-75', 'Yours is the light by which my spirit''s born: you are my sun, my moon, and all my stars.', 'E.E. Cummings', 'Romance', '["stars", "cosmos", "poetic"]', 'emerald', 0, 119),
('quote-76', 'Love is when the other person''s happiness is more important than your own.', 'H. Jackson Brown Jr.', 'Romance', '["unselfish", "devotion", "kindness"]', 'midnight', 0, 64),
('quote-77', 'You are the finest, loveliest, tenderest, and most beautiful person I have ever known — and even that is an understatement.', 'F. Scott Fitzgerald', 'Romance', '["admiration", "beauty", "reverence"]', 'nordic', 0, 133),
('quote-78', 'I am in you and you in me, mutual in divine love.', 'William Blake', 'Romance', '["mystic", "oneness", "divine"]', 'sunset', 0, 72),
('quote-79', 'We are shaped and fashioned by what we love.', 'Johann Wolfgang von Goethe', 'Romance', '["shaping", "transformation", "spirit"]', 'light', 0, 45),
('quote-80', 'Love understands love; it needs no talk.', 'Frances Ridley Havergal', 'Romance', '["silence", "understanding", "peace"]', 'emerald', 0, 64),
('quote-81', 'When I saw you I fell in love, and you smiled because you knew.', 'Arrigo Boito', 'Romance', '["knowing", "smile", "spark"]', 'midnight', 0, 47),
('quote-82', 'I cross the oceans of time to find you.', 'Bram Stoker', 'Romance', '["time", "quest", "eternity"]', 'nordic', 0, 83),
('quote-83', 'The best and most beautiful things in the world cannot be seen or even touched — they must be felt with the heart.', 'Helen Keller', 'Romance', '["heart", "beauty", "feeling"]', 'sunset', 0, 70),
('quote-84', 'How do I love thee? Let me count the ways. I love thee to the depth and breadth and height my soul can reach.', 'Elizabeth Barrett Browning', 'Romance', '["depth", "breadth", "sonnet"]', 'light', 0, 93),
('quote-85', 'Love is a game that two can play and both win.', 'Eva Gabor', 'Romance', '["playful", "harmony", "win-win"]', 'emerald', 0, 116),
('quote-86', 'In your light I learn how to love. In your beauty, how to make poems.', 'Rumi', 'Romance', '["poetry", "light", "beauty"]', 'midnight', 0, 81),
('quote-87', 'I would find you in any lifetime.', 'Kanye West', 'Romance', '["destiny", "reincarnation", "certainty"]', 'nordic', 0, 55),
('quote-88', 'A flower cannot blossom without sunshine, and man cannot live without love.', 'Max Müller', 'Romance', '["blossom", "vitality", "sun"]', 'sunset', 0, 82),
('quote-89', 'I saw that you were perfect, and so I loved you. Then I saw that you were not perfect and I loved you even more.', 'Angelita Lim', 'Romance', '["unconditional", "flaws", "grace"]', 'light', 0, 80),
('quote-90', 'You are the poem I never knew how to write, and this life is the story I have always wanted to tell.', 'Tyler Knott Gregson', 'Romance', '["poetry", "story", "life"]', 'emerald', 0, 61),
('quote-91', 'To love is nothing. To be loved is something. But to love and be loved, that’s everything.', 'T. Tolis', 'Romance', '["wholeness", "reciprocity", "truth"]', 'midnight', 0, 120),
('quote-92', 'The real lover is the man who can thrill you by kissing your forehead or smiling into your eyes.', 'Marilyn Monroe', 'Romance', '["gentleness", "intimacy", "charm"]', 'nordic', 0, 69),
('quote-93', 'I could not tell you if I loved you the first moment I saw you, or if it was the second or third or fourth. But I remember the first moment I looked at you walking toward me and realized that somehow the rest of the world seemed to vanish.', 'Cassandra Clare', 'Romance', '["world-stops", "presence", "magic"]', 'sunset', 0, 124),
('quote-94', 'Love is the flower you''ve got to let grow.', 'John Lennon', 'Romance', '["growth", "patience", "flower"]', 'light', 0, 122),
('quote-95', 'Come live with me, and be my love, and we will all the pleasures prove.', 'Christopher Marlowe', 'Romance', '["invitation", "pastoral", "pleasure"]', 'emerald', 0, 117),
('quote-96', 'You have made a place in my heart where no one else could ever go.', 'F. Scott Fitzgerald', 'Romance', '["sanctuary", "unique", "sacred"]', 'midnight', 0, 44),
('quote-97', 'For it was not into my ear you whispered, but into my heart. It was not my lips you kissed, but my soul.', 'Judy Garland', 'Romance', '["whisper", "soul", "tender"]', 'nordic', 0, 112),
('quote-98', 'Love does not dominate; it cultivates.', 'Johann Wolfgang von Goethe', 'Romance', '["cultivation", "nurture", "freedom"]', 'sunset', 0, 116),
('quote-99', 'If you live to be a hundred, I want to live to be a hundred minus one day so I never have to live without you.', 'A.A. Milne', 'Romance', '["companionship", "sweet", "devotion"]', 'light', 0, 56),
('quote-100', 'I love you as certain dark things are to be loved, in secret, between the shadow and the soul.', 'Pablo Neruda', 'Romance', '["secret", "shadow", "soul"]', 'emerald', 0, 103)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-101', 'The sea hath fish for every man, and every woman her own man; but none on earth so dear as you.', 'Christina Rossetti', 'Romance', '["treasured", "sea", "constancy"]', 'midnight', 0, 128),
('quote-102', 'You are the sun that makes my day, the moon that guides my night.', 'Lang Leav', 'Romance', '["sun", "moon", "celestial"]', 'nordic', 0, 66),
('quote-103', 'Love is an absolute necessity without which life has no meaning.', 'Daphne du Maurier', 'Romance', '["meaning", "necessity", "life"]', 'sunset', 0, 55),
('quote-104', 'I want to stand with you on a mountain, I want to bathe with you in the sea.', 'Darren Hayes', 'Romance', '["adventure", "nature", "embrace"]', 'light', 0, 94),
('quote-105', 'Your voice is full of money, she said. But his heart was full of her.', 'F. Scott Fitzgerald', 'Romance', '["wealth", "devotion", "classic"]', 'emerald', 0, 83),
('quote-106', 'You are my favorite place to go to when my mind searches for peace.', 'Nayyirah Waheed', 'Romance', '["sanctuary", "peace", "calm"]', 'midnight', 0, 69),
('quote-107', 'Where you are, that is where I want to be.', 'C.S. Lewis', 'Romance', '["presence", "nearness", "home"]', 'nordic', 0, 116),
('quote-108', 'If love is a dream, may I never wake up.', 'William Shakespeare', 'Romance', '["dream", "wonder", "sweet"]', 'sunset', 0, 123),
('quote-109', 'One smile can''t change the world, but your smile changed mine.', 'Anonymous', 'Romance', '["smile", "world", "impact"]', 'light', 0, 106),
('quote-110', 'Love is not finding someone to live with; it''s finding someone you can''t live without.', 'Rafael Ortiz', 'Romance', '["essential", "devotion", "bond"]', 'emerald', 0, 63),
('quote-111', 'I need you like a heart needs a beat.', 'OneRepublic', 'Romance', '["vital", "pulse", "rhythm"]', 'midnight', 0, 122),
('quote-112', 'Every love story is beautiful, but ours is my favorite.', 'Anonymous', 'Romance', '["story", "cherished", "sweet"]', 'nordic', 0, 76),
('quote-113', 'You are the dream I’ve been waiting to wake up to.', 'Beau Taplin', 'Romance', '["awakening", "dream", "joy"]', 'sunset', 0, 133),
('quote-114', 'In your smile I see something more beautiful than the stars.', 'Beth Revis', 'Romance', '["stars", "smile", "radiance"]', 'light', 0, 134),
('quote-115', 'My soul and your soul are forever tangled.', 'N.R. Hart', 'Romance', '["tangled", "entwined", "eternity"]', 'emerald', 0, 42),
('quote-116', 'I choose you. And I''ll choose you over and over and over. Without pause, without a doubt, in a heartbeat.', 'Anonymous', 'Romance', '["choice", "commitment", "steadfast"]', 'midnight', 0, 64),
('quote-117', 'You are my blue crayon, the one I never have enough of, the one I use to color my sky.', 'A.R. Asher', 'Romance', '["color", "sky", "artistic"]', 'nordic', 0, 140),
('quote-118', 'When I follow my heart, it leads me to you.', 'Anonymous', 'Romance', '["compass", "heart", "guidance"]', 'sunset', 0, 39),
('quote-119', 'Love is when you look into someone''s eyes and see everything you need.', 'Anonymous', 'Romance', '["eyes", "completeness", "home"]', 'light', 0, 138),
('quote-120', 'I love you more than yesterday, less than tomorrow.', 'Edmond Rostand', 'Romance', '["growing", "daily", "cyrano"]', 'emerald', 0, 75),
('quote-121', 'The sound of your voice is my favorite lullaby.', 'Anonymous', 'Romance', '["voice", "comfort", "melody"]', 'midnight', 0, 86),
('quote-122', 'Distance means so little when someone means so much.', 'Tom McNeal', 'Romance', '["distance", "constancy", "faith"]', 'nordic', 0, 69),
('quote-123', 'I fell in love with your soul before I could even touch your skin.', 'Anonymous', 'Romance', '["soul-first", "connection", "depth"]', 'sunset', 0, 43),
('quote-124', 'You make me feel like I am home.', 'Anonymous', 'Romance', '["belonging", "comfort", "shelter"]', 'light', 0, 62),
('quote-125', 'I love you for all that you are, all that you have been, and all that you''re yet to be.', 'Anonymous', 'Romance', '["acceptance", "eternity", "grace"]', 'emerald', 0, 107),
('quote-126', 'My heart beats faster when you whisper my name.', 'Anonymous', 'Romance', '["whisper", "pulse", "intimacy"]', 'midnight', 0, 126),
('quote-127', 'With you, time stands completely still.', 'Anonymous', 'Romance', '["timeless", "moment", "magic"]', 'nordic', 0, 75),
('quote-128', 'I have loved you all my life, it has just taken me this long to find you.', 'Anonymous', 'Romance', '["lifelong", "destiny", "found"]', 'sunset', 0, 62),
('quote-129', 'You are the sweetest chapter in my book of life.', 'Anonymous', 'Romance', '["chapter", "story", "sweetness"]', 'light', 0, 118),
('quote-130', 'If our love were a painting, it would be a masterpiece.', 'Anonymous', 'Romance', '["masterpiece", "canvas", "harmony"]', 'emerald', 0, 98),
('quote-131', 'The warmth of your hand in mine is all the proof I need of heaven.', 'Anonymous', 'Romance', '["heaven", "touch", "peace"]', 'midnight', 0, 85),
('quote-132', 'You are my favorite thought before I drift to sleep.', 'Anonymous', 'Romance', '["night", "thought", "gentle"]', 'nordic', 0, 117),
('quote-133', 'You are the anchor to my drifting heart.', 'Anonymous', 'Romance', '["anchor", "safety", "steadfast"]', 'sunset', 0, 93),
('quote-134', 'No measure of time with you will be long enough, but let''s start with forever.', 'Stephenie Meyer', 'Romance', '["forever", "beginning", "time"]', 'light', 0, 53),
('quote-135', 'In a sea of people, my eyes will always search for you.', 'Anonymous', 'Romance', '["gaze", "devotion", "search"]', 'emerald', 0, 68),
('quote-136', 'You are the music my heart beats to.', 'Anonymous', 'Romance', '["music", "harmony", "rhythm"]', 'midnight', 0, 52),
('quote-137', 'Loving you is like breathing; how could I ever stop?', 'Anonymous', 'Romance', '["natural", "essential", "breath"]', 'nordic', 0, 66),
('quote-138', 'You gave my heart wings and taught my soul how to fly.', 'Anonymous', 'Romance', '["wings", "freedom", "flight"]', 'sunset', 0, 130),
('quote-139', 'I find pieces of you in every sunset I watch.', 'Anonymous', 'Romance', '["sunset", "memory", "beauty"]', 'light', 0, 106),
('quote-140', 'You are my greatest adventure and my safest haven.', 'Anonymous', 'Romance', '["adventure", "haven", "balance"]', 'emerald', 0, 103),
('quote-141', 'Every beat of my heart whispers your name.', 'Anonymous', 'Romance', '["whisper", "heartbeat", "devotion"]', 'midnight', 0, 68),
('quote-142', 'Your touch writes poetry upon my skin.', 'Anonymous', 'Romance', '["touch", "poetry", "intimate"]', 'nordic', 0, 130),
('quote-143', 'You turned my ordinary days into a story worth reading.', 'Anonymous', 'Romance', '["magic", "transformation", "narrative"]', 'sunset', 0, 109),
('quote-144', 'I love you not only for what you are, but for what I am when I am with you.', 'Roy Croft', 'Romance', '["reflection", "growth", "companion"]', 'light', 0, 89),
('quote-145', 'You are the dawn after my longest night.', 'Anonymous', 'Romance', '["dawn", "light", "hope"]', 'emerald', 0, 109),
('quote-146', 'Forever is a long time, but I wouldn''t mind spending it by your side.', 'Anonymous', 'Romance', '["eternity", "side-by-side", "sweet"]', 'midnight', 0, 86),
('quote-147', 'You are the stillness in my chaotic mind.', 'Anonymous', 'Romance', '["calm", "serenity", "anchor"]', 'nordic', 0, 81),
('quote-148', 'Your laughter is my favorite melody in this noisy world.', 'Anonymous', 'Romance', '["laughter", "joy", "melody"]', 'sunset', 0, 63),
('quote-149', 'To the world you may be one person, but to one person you may be the world.', 'Dr. Seuss', 'Romance', '["universe", "cherished", "individual"]', 'light', 0, 52),
('quote-150', 'You are my North Star, guiding me home across the darkest seas.', 'Anonymous', 'Romance', '["compass", "north-star", "guidance"]', 'emerald', 0, 100),
('quote-151', 'Two hearts, one journey, infinite love.', 'Anonymous', 'Romance', '["journey", "infinity", "union"]', 'midnight', 0, 98),
('quote-152', 'I will love you until the stars go out and the tides no longer turn.', 'Anonymous', 'Romance', '["cosmic", "unending", "tides"]', 'nordic', 0, 46),
('quote-153', 'You are the spark that ignited a symphony in my heart.', 'Anonymous', 'Romance', '["symphony", "spark", "music"]', 'sunset', 0, 131),
('quote-154', 'In your embrace, I have found my forever sanctuary.', 'Anonymous', 'Romance', '["sanctuary", "embrace", "peace"]', 'light', 0, 41),
('quote-155', 'You are the secret wish I whisper to every falling star.', 'Anonymous', 'Romance', '["shooting-star", "wish", "dream"]', 'emerald', 0, 49),
('quote-156', 'Every kiss from you is a promise carved into eternity.', 'Anonymous', 'Romance', '["promise", "eternity", "kiss"]', 'midnight', 0, 54),
('quote-157', 'Our love is an echo that will ring through the universe forever.', 'Anonymous', 'Romance', '["echo", "universe", "timeless"]', 'nordic', 0, 115),
('quote-158', 'You are the soft rain that brings my garden into bloom.', 'Anonymous', 'Romance', '["gentle", "bloom", "rain"]', 'sunset', 0, 55),
('quote-159', 'Loving you is the easiest, most natural thing I have ever done.', 'Anonymous', 'Romance', '["effortless", "natural", "joy"]', 'light', 0, 136),
('quote-160', 'My soul knew yours before our eyes ever met.', 'Anonymous', 'Romance', '["soulmate", "ancient", "destiny"]', 'emerald', 0, 122),
('quote-161', 'You are the poetry written between the lines of my life.', 'Anonymous', 'Romance', '["poetry", "subtle", "depth"]', 'midnight', 0, 89),
('quote-162', 'I look at you and see the rest of my days painted in golden light.', 'Anonymous', 'Romance', '["golden", "future", "light"]', 'nordic', 0, 111),
('quote-163', 'You are my heart''s undisputed home.', 'Anonymous', 'Romance', '["home", "anchor", "certainty"]', 'sunset', 0, 43),
('quote-164', 'If stars could speak, they would tell you how deeply I adore you.', 'Anonymous', 'Romance', '["starlight", "cosmic", "adoration"]', 'light', 0, 84),
('quote-165', 'Your love is the gentle breeze that sails my ship into harbor.', 'Anonymous', 'Romance', '["harbor", "breeze", "safety"]', 'emerald', 0, 83),
('quote-166', 'You are my sunrise in winter and my shade in summer.', 'Anonymous', 'Romance', '["comfort", "seasons", "shelter"]', 'midnight', 0, 111),
('quote-167', 'Every second spent loving you is a second spent living fully.', 'Anonymous', 'Romance', '["living", "presence", "fullness"]', 'nordic', 0, 94),
('quote-168', 'With you, even the silence speaks of tenderness.', 'Anonymous', 'Romance', '["silence", "gentleness", "peace"]', 'sunset', 0, 102),
('quote-169', 'You are the fire in my winter and the coolness in my desert.', 'Anonymous', 'Romance', '["balance", "elements", "refuge"]', 'light', 0, 67),
('quote-170', 'Our love is written in the constellations.', 'Anonymous', 'Romance', '["constellation", "destiny", "cosmos"]', 'emerald', 0, 105),
('quote-171', 'You are the reason my eyes light up and my heart feels brave.', 'Anonymous', 'Romance', '["bravery", "light", "spark"]', 'midnight', 0, 36),
('quote-172', 'I love you more than all the words ever spoken by all the poets in time.', 'Anonymous', 'Romance', '["boundless", "poetry", "devotion"]', 'nordic', 0, 122),
('quote-173', 'To hold you close is to hold all the miracles of the earth.', 'Anonymous', 'Romance', '["miracle", "earth", "embrace"]', 'sunset', 0, 127),
('quote-174', 'You have power over your mind - not outside events. Realize this, and you will find strength.', 'Marcus Aurelius', 'Stoicism', '["mindset", "resilience", "clarity"]', 'light', 0, 49),
('quote-175', 'We suffer more often in imagination than in reality.', 'Seneca', 'Stoicism', '["anxiety", "perspective", "wisdom"]', 'emerald', 0, 122),
('quote-176', 'No person has the power to have everything they want, but it is in their power not to want what they have not, and cheerfully to put to good use what they have.', 'Seneca', 'Stoicism', '["contentment", "gratitude"]', 'midnight', 0, 103),
('quote-177', 'Waste no more time arguing about what a good man should be. Be one.', 'Marcus Aurelius', 'Stoicism', '["action", "character", "integrity"]', 'nordic', 0, 131),
('quote-178', 'It is not death that a man should fear, but he should fear never beginning to live.', 'Marcus Aurelius', 'Stoicism', '["courage", "purpose"]', 'sunset', 0, 69),
('quote-179', 'Difficulties strengthen the mind, as labor does the body.', 'Seneca', 'Stoicism', '["growth", "adversity", "grit"]', 'light', 0, 133),
('quote-180', 'If anyone can refute me, show me I''m making a mistake, I''ll gladly change. I seek the truth, which never harmed anyone.', 'Marcus Aurelius', 'Stoicism', '["humility", "truth", "learning"]', 'emerald', 0, 117),
('quote-181', 'He who fears death will never do anything worthy of a man who is alive.', 'Seneca', 'Stoicism', '["fearlessness", "action"]', 'midnight', 0, 78),
('quote-182', 'Wealth consists not in having great possessions, but in having few wants.', 'Epictetus', 'Stoicism', '["simplicity", "wealth", "freedom"]', 'nordic', 0, 49),
('quote-183', 'Man is not worried by real problems so much as by his imagined anxieties about real problems.', 'Epictetus', 'Stoicism', '["anxiety", "mind", "control"]', 'sunset', 0, 72),
('quote-184', 'Don''t explain your philosophy. Embody it.', 'Epictetus', 'Stoicism', '["action", "deeds", "authenticity"]', 'light', 0, 90),
('quote-185', 'The soul becomes dyed with the color of its thoughts.', 'Marcus Aurelius', 'Stoicism', '["thoughts", "mind", "character"]', 'emerald', 0, 55),
('quote-186', 'First say to yourself what you would be; and then do what you have to do.', 'Epictetus', 'Stoicism', '["identity", "action", "purpose"]', 'midnight', 0, 93),
('quote-187', 'If a man knows not to which port he sails, no wind is favorable.', 'Seneca', 'Stoicism', '["direction", "purpose", "clarity"]', 'nordic', 0, 35),
('quote-188', 'Begin at once to live, and count each separate day as a separate life.', 'Seneca', 'Stoicism', '["present", "mindfulness", "gratitude"]', 'sunset', 0, 127),
('quote-189', 'Dwell on the beauty of life. Watch the stars, and see yourself running with them.', 'Marcus Aurelius', 'Stoicism', '["beauty", "wonder", "stars"]', 'light', 0, 127),
('quote-190', 'The best revenge is not to be like that.', 'Marcus Aurelius', 'Stoicism', '["character", "integrity", "revenge"]', 'emerald', 0, 68),
('quote-191', 'It is not that we have a short time to live, but that we waste a lot of it.', 'Seneca', 'Stoicism', '["time", "presence", "focus"]', 'midnight', 0, 99),
('quote-192', 'He is a wise man who does not grieve for the things which he has not, but rejoices for those which he has.', 'Epictetus', 'Stoicism', '["gratitude", "wisdom", "joy"]', 'nordic', 0, 132),
('quote-193', 'How much trouble he avoids who does not look to see what his neighbor says or does or thinks.', 'Marcus Aurelius', 'Stoicism', '["focus", "boundaries", "peace"]', 'sunset', 0, 57),
('quote-194', 'Freedom is the only worthy goal in life. It is won by disregarding things that lie beyond our control.', 'Epictetus', 'Stoicism', '["freedom", "control", "liberty"]', 'light', 0, 99),
('quote-195', 'Luck is what happens when preparation meets opportunity.', 'Seneca', 'Stoicism', '["luck", "preparation", "readiness"]', 'emerald', 0, 48),
('quote-196', 'Reject your sense of injury and the injury itself disappears.', 'Marcus Aurelius', 'Stoicism', '["resilience", "perception", "mind"]', 'midnight', 0, 115),
('quote-197', 'Nothing, to my way of thinking, is a better proof of a well-ordered mind than a man''s ability to stop where he is and pass some time in his own company.', 'Seneca', 'Stoicism', '["solitude", "mind", "peace"]', 'nordic', 0, 73),
('quote-198', 'Receive without conceit, release without struggle.', 'Marcus Aurelius', 'Stoicism', '["detachment", "grace", "humility"]', 'sunset', 0, 116),
('quote-199', 'To be calm is the highest achievement of the self.', 'Zen Proverb', 'Stoicism', '["calm", "stillness", "mastery"]', 'light', 0, 99),
('quote-200', 'Only time can heal what reason cannot.', 'Seneca', 'Stoicism', '["healing", "time", "patience"]', 'emerald', 0, 112)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-201', 'Think of yourself as dead. You have lived your life. Now, take what''s left and live it properly.', 'Marcus Aurelius', 'Stoicism', '["memento-mori", "rebirth", "clarity"]', 'midnight', 0, 60),
('quote-202', 'Small-minded people blame others. Average people blame themselves. The wise see all blame as foolishness.', 'Epictetus', 'Stoicism', '["wisdom", "responsibility", "maturity"]', 'nordic', 0, 54),
('quote-203', 'There is only one way to happiness and that is to cease worrying about things which are beyond the power of our will.', 'Epictetus', 'Stoicism', '["serenity", "worry", "peace"]', 'sunset', 0, 82),
('quote-204', 'A gem cannot be polished without friction, nor a man perfected without trials.', 'Seneca', 'Stoicism', '["trials", "grit", "refinement"]', 'light', 0, 132),
('quote-205', 'The happiness of your life depends upon the quality of your thoughts.', 'Marcus Aurelius', 'Stoicism', '["thoughts", "happiness", "quality"]', 'emerald', 0, 55),
('quote-206', 'No man is free who is not master of himself.', 'Epictetus', 'Stoicism', '["self-mastery", "discipline", "freedom"]', 'midnight', 0, 104),
('quote-207', 'When you arise in the morning think of what a privilege it is to be alive, to think, to enjoy, to love.', 'Marcus Aurelius', 'Stoicism', '["morning", "privilege", "gratitude"]', 'nordic', 0, 134),
('quote-208', 'Caretake your thoughts; what you think today determines what you build tomorrow.', 'Marcus Aurelius', 'Stoicism', '["vision", "thoughts", "destiny"]', 'sunset', 0, 102),
('quote-209', 'Hang on to your youthful enthusiasms — you''ll be able to use them better when you''re older.', 'Seneca', 'Stoicism', '["youth", "enthusiasm", "vitality"]', 'light', 0, 35),
('quote-210', 'If you are pained by any external thing, it is not this thing that disturbs you, but your own judgment about it.', 'Marcus Aurelius', 'Stoicism', '["perception", "mind", "stoic"]', 'emerald', 0, 111),
('quote-211', 'It is the power of the mind to be unconquerable.', 'Seneca', 'Stoicism', '["unconquerable", "strength", "power"]', 'midnight', 0, 76),
('quote-212', 'Never let the future disturb you. You will meet it, if you have to, with the same weapons of reason which today arm you against the present.', 'Marcus Aurelius', 'Stoicism', '["future", "reason", "calm"]', 'nordic', 0, 97),
('quote-213', 'Associate with people who are likely to improve you.', 'Seneca', 'Stoicism', '["community", "growth", "standards"]', 'sunset', 0, 37),
('quote-214', 'Attach yourself to what is spiritually superior, regardless of what other people think or do.', 'Epictetus', 'Stoicism', '["standards", "spirituality", "integrity"]', 'light', 0, 49),
('quote-215', 'Be tolerant with others and strict with yourself.', 'Marcus Aurelius', 'Stoicism', '["discipline", "compassion", "humility"]', 'emerald', 0, 81),
('quote-216', 'He who indulges in empty fears earns himself real fears.', 'Seneca', 'Stoicism', '["fear", "reality", "mind"]', 'midnight', 0, 138),
('quote-217', 'How ridiculous and what a stranger he is who is surprised by anything which happens in life.', 'Marcus Aurelius', 'Stoicism', '["acceptance", "serenity", "equanimity"]', 'nordic', 0, 74),
('quote-218', 'True happiness is to enjoy the present, without anxious dependence upon the future.', 'Seneca', 'Stoicism', '["present", "happiness", "now"]', 'sunset', 0, 65),
('quote-219', 'The impediment to action advances action. What stands in the way becomes the way.', 'Marcus Aurelius', 'Stoicism', '["obstacle", "action", "opportunity"]', 'light', 0, 42),
('quote-220', 'No great thing is created suddenly, any more than a bunch of grapes or a fig.', 'Epictetus', 'Stoicism', '["patience", "growth", "mastery"]', 'emerald', 0, 65),
('quote-221', 'Every night before going to sleep, we must ask ourselves: what weakness did I overcome today? What virtue did I acquire?', 'Seneca', 'Stoicism', '["self-reflection", "virtue", "growth"]', 'midnight', 0, 107),
('quote-222', 'Life is very short and anxious for those who forget the past, neglect the present, and fear the future.', 'Seneca', 'Stoicism', '["time", "mindfulness", "anxiety"]', 'nordic', 0, 45),
('quote-223', 'Accept the things to which fate binds you, and love the people with whom fate brings you together, but do so with all your heart.', 'Marcus Aurelius', 'Stoicism', '["amor-fati", "acceptance", "love"]', 'sunset', 0, 45),
('quote-224', 'Circumstances don''t make the man, they only reveal him to himself.', 'Epictetus', 'Stoicism', '["character", "circumstance", "truth"]', 'light', 0, 128),
('quote-225', 'Sometimes even to live is an act of courage.', 'Seneca', 'Stoicism', '["courage", "resilience", "survival"]', 'emerald', 0, 97),
('quote-226', 'If it is not right, do not do it; if it is not true, do not say it.', 'Marcus Aurelius', 'Stoicism', '["truth", "integrity", "simplicity"]', 'midnight', 0, 139),
('quote-227', 'No man was ever wise by chance.', 'Seneca', 'Stoicism', '["deliberate", "wisdom", "effort"]', 'nordic', 0, 43),
('quote-228', 'He who laughs at himself never runs out of things to laugh at.', 'Epictetus', 'Stoicism', '["humor", "humility", "perspective"]', 'sunset', 0, 132),
('quote-229', 'Do every act of your life as though it were the very last act of your life.', 'Marcus Aurelius', 'Stoicism', '["presence", "urgency", "focus"]', 'light', 0, 103),
('quote-230', 'As is a tale, so is life: not how long it is, but how good it is, is what matters.', 'Seneca', 'Stoicism', '["meaning", "quality", "story"]', 'emerald', 0, 133),
('quote-231', 'It is not the man who has too little, but the man who craves more, that is poor.', 'Seneca', 'Stoicism', '["contentment", "wealth", "greed"]', 'midnight', 0, 51),
('quote-232', 'Don''t demand that things happen as you wish, but wish that they happen as they do happen, and you will go on well.', 'Epictetus', 'Stoicism', '["acceptance", "flow", "peace"]', 'nordic', 0, 51),
('quote-233', 'Whatever anyone does or says, I must be emerald and keep my color.', 'Marcus Aurelius', 'Stoicism', '["integrity", "constancy", "emerald"]', 'sunset', 0, 119),
('quote-234', 'The mind that is anxious about future events is miserable.', 'Seneca', 'Stoicism', '["anxiety", "peace", "now"]', 'light', 0, 95),
('quote-235', 'The blazing fire makes flame and brightness out of everything that is thrown into it.', 'Marcus Aurelius', 'Stoicism', '["adversity", "alchemy", "fuel"]', 'emerald', 0, 105),
('quote-236', 'Let silence be your general rule; or say only what is necessary and in few words.', 'Epictetus', 'Stoicism', '["silence", "discernment", "speech"]', 'midnight', 0, 56),
('quote-237', 'Ignorance is the cause of fear.', 'Seneca', 'Stoicism', '["knowledge", "courage", "clarity"]', 'nordic', 0, 68),
('quote-238', 'Forward, as occasion offers. Never look round to see whether any shall note it.', 'Marcus Aurelius', 'Stoicism', '["modesty", "progress", "duty"]', 'sunset', 0, 102),
('quote-239', 'Practice what you preach, or keep quiet.', 'Musonius Rufus', 'Stoicism', '["deeds", "authenticity", "integrity"]', 'light', 0, 112),
('quote-240', 'Excellence is an art won by training and habituation.', 'Aristotle', 'Stoicism', '["habit", "excellence", "discipline"]', 'emerald', 0, 89),
('quote-241', 'To bear trials with a calm mind robs misfortune of its strength and burden.', 'Seneca', 'Stoicism', '["calm", "misfortune", "resilience"]', 'midnight', 0, 62),
('quote-242', 'Very little is needed to make a happy life; it is all within yourself, in your way of thinking.', 'Marcus Aurelius', 'Stoicism', '["simplicity", "happiness", "mind"]', 'nordic', 0, 104),
('quote-243', 'Nothing is burdensome if taken lightly, and nothing need arouse one''s irritation so long as one doesn''t make it worse by one''s own irritation.', 'Seneca', 'Stoicism', '["lightness", "reaction", "peace"]', 'sunset', 0, 131),
('quote-244', 'The greater the difficulty, the more glory in overcoming it.', 'Epicurus', 'Stoicism', '["difficulty", "triumph", "glory"]', 'light', 0, 128),
('quote-245', 'You always own the option of having no opinion.', 'Marcus Aurelius', 'Stoicism', '["opinion", "peace", "restraint"]', 'emerald', 0, 123),
('quote-246', 'Begin each day by telling yourself: Today I shall meet with interference, ingratitude, insolence, disloyalty, ill-will, and selfishness.', 'Marcus Aurelius', 'Stoicism', '["preparation", "compassion", "realism"]', 'midnight', 0, 60),
('quote-247', 'Regard friend as loyal, and you will make him loyal.', 'Seneca', 'Stoicism', '["trust", "friendship", "loyalty"]', 'nordic', 0, 126),
('quote-248', 'The key is to keep company only with people who uplift you, whose presence calls forth your best.', 'Epictetus', 'Stoicism', '["standards", "company", "uplift"]', 'sunset', 0, 74),
('quote-249', 'Do not spoil what you have by desiring what you have not.', 'Epicurus', 'Stoicism', '["gratitude", "contentment", "peace"]', 'light', 0, 86),
('quote-250', 'Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.', 'Marcus Aurelius', 'Stoicism', '["inner-depth", "goodness", "source"]', 'emerald', 0, 120),
('quote-251', 'To be like the rock that the waves keep crashing over. It stands unmoved and the raging of the sea falls still around it.', 'Marcus Aurelius', 'Stoicism', '["rock", "stillness", "unmoved"]', 'midnight', 0, 118),
('quote-252', 'We are like passengers on a ship; we can steer with wisdom even when the storms rage.', 'Epictetus', 'Stoicism', '["stewardship", "wisdom", "storm"]', 'nordic', 0, 82),
('quote-253', 'Live out your life in truth and justice, tolerant of those who are neither true nor just.', 'Marcus Aurelius', 'Stoicism', '["tolerance", "justice", "truth"]', 'sunset', 0, 91),
('quote-254', 'Leisure without study is death: it is a tomb for the living man.', 'Seneca', 'Stoicism', '["study", "mind", "curiosity"]', 'light', 0, 101),
('quote-255', 'Never claim to be a wise person, nor talk much among the unlearned about your principles.', 'Epictetus', 'Stoicism', '["humility", "quiet", "practice"]', 'emerald', 0, 92),
('quote-256', 'A man''s worth is no greater than his ambitions.', 'Marcus Aurelius', 'Stoicism', '["ambition", "worth", "striving"]', 'midnight', 0, 50),
('quote-257', 'The mind is the ruler of the soul.', 'Seneca', 'Stoicism', '["mastery", "ruler", "soul"]', 'nordic', 0, 66),
('quote-258', 'Let your desire be to contemplate the infinite cosmos.', 'Marcus Aurelius', 'Stoicism', '["cosmos", "perspective", "infinite"]', 'sunset', 0, 63),
('quote-259', 'Life is like a play: it''s not the length, but the excellence of the acting that matters.', 'Seneca', 'Stoicism', '["excellence", "drama", "living"]', 'light', 0, 43),
('quote-260', 'Wisdom is the only freedom.', 'Seneca', 'Stoicism', '["freedom", "wisdom", "liberty"]', 'emerald', 0, 78),
('quote-261', 'Calmness is a superpower in a turbulent world.', 'Marcus Aurelius', 'Stoicism', '["calm", "superpower", "stillness"]', 'midnight', 0, 37),
('quote-262', 'When you conquer your own mind, you conquer the entire world.', 'Marcus Aurelius', 'Stoicism', '["victory", "mind", "mastery"]', 'nordic', 0, 110),
('quote-263', 'Every new day is an unwritten page of virtue.', 'Seneca', 'Stoicism', '["fresh", "virtue", "dawn"]', 'sunset', 0, 105),
('quote-264', 'Hold fast to your center and let the chaos swirl without touching you.', 'Marcus Aurelius', 'Stoicism', '["center", "anchor", "peace"]', 'light', 0, 64),
('quote-265', 'Stand firm as a tower that never shakes its summit though the winds blow.', 'Dante Alighieri', 'Stoicism', '["firmness", "tower", "resolve"]', 'emerald', 0, 110),
('quote-266', 'Self-control is strength. Right thought is mastery. Calmness is power.', 'James Allen', 'Stoicism', '["strength", "mastery", "power"]', 'midnight', 0, 63),
('quote-267', 'Your mind will take the shape of what you frequently hold in thought.', 'Marcus Aurelius', 'Stoicism', '["habits", "thoughts", "shape"]', 'nordic', 0, 35),
('quote-268', 'The greatest step toward tranquility is learning to let go.', 'Epictetus', 'Stoicism', '["letting-go", "tranquility", "peace"]', 'sunset', 0, 44),
('quote-269', 'A soul that knows peace cannot be shaken by the noise of the world.', 'Seneca', 'Stoicism', '["peace", "noise", "serenity"]', 'light', 0, 125),
('quote-270', 'Turn your attention inward and you will find an ocean of stillness.', 'Marcus Aurelius', 'Stoicism', '["inward", "ocean", "stillness"]', 'emerald', 0, 115),
('quote-271', 'Every obstacle is merely an invitation to practice courage.', 'Marcus Aurelius', 'Stoicism', '["obstacle", "invitation", "courage"]', 'midnight', 0, 42),
('quote-272', 'Act with clarity, speak with honesty, live with purpose.', 'Seneca', 'Stoicism', '["clarity", "honesty", "purpose"]', 'nordic', 0, 64),
('quote-273', 'You are not what happened to you; you are what you choose to become.', 'Carl Jung', 'Stoicism', '["choice", "identity", "growth"]', 'sunset', 0, 43),
('quote-274', 'The true measure of a man is how he treats someone who can do him no good.', 'Samuel Johnson', 'Stoicism', '["integrity", "kindness", "measure"]', 'light', 0, 39),
('quote-275', 'Master your passions or they will master you.', 'Epictetus', 'Stoicism', '["discipline", "passions", "control"]', 'emerald', 0, 77),
('quote-276', 'Strength comes from knowing what you cannot change and mastering what you can.', 'Seneca', 'Stoicism', '["wisdom", "discernment", "strength"]', 'midnight', 0, 44),
('quote-277', 'Let virtue be your only compass.', 'Marcus Aurelius', 'Stoicism', '["compass", "virtue", "guidance"]', 'nordic', 0, 100),
('quote-278', 'The peaceful mind is the greatest fortress in existence.', 'Marcus Aurelius', 'Stoicism', '["fortress", "peace", "protection"]', 'sunset', 0, 65),
('quote-279', 'Cultivate an unshakeable spirit in the face of uncertainty.', 'Seneca', 'Stoicism', '["spirit", "uncertainty", "unshakeable"]', 'light', 0, 70),
('quote-280', 'In the midst of chaos, discover your sanctuary within.', 'Marcus Aurelius', 'Stoicism', '["sanctuary", "inner", "calm"]', 'emerald', 0, 120),
('quote-281', 'To endure trials with dignity is the highest mark of noble character.', 'Seneca', 'Stoicism', '["dignity", "trials", "character"]', 'midnight', 0, 97),
('quote-282', 'Do not be distracted by the applause or the criticism of the crowd.', 'Marcus Aurelius', 'Stoicism', '["independence", "focus", "freedom"]', 'nordic', 0, 62),
('quote-283', 'Each moment is a sacred chance to act rightly.', 'Marcus Aurelius', 'Stoicism', '["sacred", "right-action", "now"]', 'sunset', 0, 104),
('quote-284', 'Peace comes from within. Do not seek it without.', 'Buddha', 'Mindfulness', '["inner-peace", "clarity", "spirit"]', 'light', 0, 51),
('quote-285', 'The present moment is filled with joy and happiness. If you are attentive, you will see it.', 'Thich Nhat Hanh', 'Mindfulness', '["presence", "joy", "awareness"]', 'emerald', 0, 127),
('quote-286', 'Smile, breathe, and go slowly.', 'Thich Nhat Hanh', 'Mindfulness', '["gentleness", "breath", "pacing"]', 'midnight', 0, 108),
('quote-287', 'Feelings come and go like clouds in a windy sky. Conscious breathing is my anchor.', 'Thich Nhat Hanh', 'Mindfulness', '["breath", "anchor", "calm"]', 'nordic', 0, 108),
('quote-288', 'Do not dwell in the past, do not dream of the future, concentrate the mind on the present moment.', 'Buddha', 'Mindfulness', '["now", "focus", "presence"]', 'sunset', 0, 95),
('quote-289', 'Silence is not empty, it is full of answers.', 'Rumi', 'Mindfulness', '["silence", "listening", "wisdom"]', 'light', 0, 66),
('quote-290', 'To the mind that is still, the whole universe surrenders.', 'Lao Tzu', 'Mindfulness', '["stillness", "tao", "universe"]', 'emerald', 0, 135),
('quote-291', 'Surrender to what is. Say ''yes'' to life — and see how life suddenly starts working for you rather than against you.', 'Eckhart Tolle', 'Mindfulness', '["surrender", "acceptance", "flow"]', 'midnight', 0, 95),
('quote-292', 'The primary cause of unhappiness is never the situation but your thoughts about it.', 'Eckhart Tolle', 'Mindfulness', '["thoughts", "unhappiness", "clarity"]', 'nordic', 0, 138),
('quote-293', 'Muddy water is best cleared by leaving it alone.', 'Alan Watts', 'Mindfulness', '["patience", "clarity", "stillness"]', 'sunset', 0, 87),
('quote-294', 'You cannot travel the path until you have become the path itself.', 'Buddha', 'Mindfulness', '["embodiment", "journey", "truth"]', 'light', 0, 59),
('quote-295', 'Breath is the bridge which connects life to consciousness, which unites your body to your thoughts.', 'Thich Nhat Hanh', 'Mindfulness', '["breath", "bridge", "unity"]', 'emerald', 0, 47),
('quote-296', 'Nature does not hurry, yet everything is accomplished.', 'Lao Tzu', 'Mindfulness', '["nature", "patience", "timing"]', 'midnight', 0, 47),
('quote-297', 'When you let go of what you are, you become what you might be.', 'Lao Tzu', 'Mindfulness', '["transformation", "letting-go", "potential"]', 'nordic', 0, 119),
('quote-298', 'In the midst of movement and chaos, keep stillness inside of you.', 'Deepak Chopra', 'Mindfulness', '["stillness", "chaos", "center"]', 'sunset', 0, 90),
('quote-299', 'Mindfulness is simply being aware of what is happening right now without wishing it were any different.', 'James Baraz', 'Mindfulness', '["acceptance", "awareness", "now"]', 'light', 0, 80),
('quote-300', 'Quiet the mind, and the soul will speak.', 'Ma Jaya Sati Bhagavati', 'Mindfulness', '["quiet", "soul", "listening"]', 'emerald', 0, 89)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-301', 'Drink your tea slowly and reverently, as if it is the axis on which the world earth revolves.', 'Thich Nhat Hanh', 'Mindfulness', '["tea", "reverence", "ritual"]', 'midnight', 0, 87),
('quote-302', 'The only way to live is by accepting each minute as an unrepeatable miracle.', 'Tara Brach', 'Mindfulness', '["miracle", "presence", "gratitude"]', 'nordic', 0, 94),
('quote-303', 'Look at a tree, a flower, a plant. Let your awareness rest upon it. How still they are, how deeply rooted in Being.', 'Eckhart Tolle', 'Mindfulness', '["nature", "stillness", "being"]', 'sunset', 0, 128),
('quote-304', 'Life is a dance. Mindfulness is witnessing that dance.', 'Amit Ray', 'Mindfulness', '["dance", "witness", "joy"]', 'light', 0, 41),
('quote-305', 'Nothing is permanent in this wicked world - not even our troubles.', 'Charlie Chaplin', 'Mindfulness', '["impermanence", "perspective", "hope"]', 'emerald', 0, 121),
('quote-306', 'Be where you are, otherwise you will miss your life.', 'Buddha', 'Mindfulness', '["presence", "living", "now"]', 'midnight', 0, 118),
('quote-307', 'Your calm mind is the ultimate weapon against your challenges.', 'Bryant McGill', 'Mindfulness', '["calm", "mindset", "strength"]', 'nordic', 0, 117),
('quote-308', 'Within you, there is a stillness and a sanctuary to which you can retreat at any time and be yourself.', 'Hermann Hesse', 'Mindfulness', '["sanctuary", "inner", "retreat"]', 'sunset', 0, 47),
('quote-309', 'When you realize nothing is lacking, the whole world belongs to you.', 'Lao Tzu', 'Mindfulness', '["abundance", "contentment", "tao"]', 'light', 0, 42),
('quote-310', 'Tension is who you think you should be. Relaxation is who you are.', 'Chinese Proverb', 'Mindfulness', '["relaxation", "authenticity", "peace"]', 'emerald', 0, 86),
('quote-311', 'The soul loves to meditate, for in silence it connects with eternity.', 'Paramahansa Yogananda', 'Mindfulness', '["meditation", "silence", "eternity"]', 'midnight', 0, 128),
('quote-312', 'Slow down and enjoy life. It''s not only the scenery you miss by going too fast - you also miss the sense of where you are going and why.', 'Eddie Cantor', 'Mindfulness', '["slow-down", "pacing", "clarity"]', 'nordic', 0, 78),
('quote-313', 'One conscious breathe in and out is a meditation.', 'Eckhart Tolle', 'Mindfulness', '["breath", "simplicity", "meditation"]', 'sunset', 0, 137),
('quote-314', 'The root of all suffering is attachment.', 'Buddha', 'Mindfulness', '["attachment", "detachment", "suffering"]', 'light', 0, 48),
('quote-315', 'Do whatever you are doing right now with 100% of your heart.', 'Thich Nhat Hanh', 'Mindfulness', '["wholehearted", "focus", "presence"]', 'emerald', 0, 66),
('quote-316', 'Wherever you are, be there totally.', 'Eckhart Tolle', 'Mindfulness', '["totality", "presence", "immersion"]', 'midnight', 0, 59),
('quote-317', 'Nothing can bring you peace but yourself.', 'Ralph Waldo Emerson', 'Mindfulness', '["inner-peace", "self-reliance", "truth"]', 'nordic', 0, 59),
('quote-318', 'Everything that has a beginning has an ending. Make your peace with that and all will be well.', 'Jack Kornfield', 'Mindfulness', '["impermanence", "peace", "cycles"]', 'sunset', 0, 103),
('quote-319', 'Observe without judgment, and clarity will arise naturally.', 'Jiddu Krishnamurti', 'Mindfulness', '["observation", "clarity", "nonjudgment"]', 'light', 0, 92),
('quote-320', 'Wisdom begins with the pause between thought and action.', 'Viktor Frankl', 'Mindfulness', '["pause", "choice", "space"]', 'emerald', 0, 52),
('quote-321', 'When we are present, we have already arrived.', 'Thich Nhat Hanh', 'Mindfulness', '["arrived", "presence", "peace"]', 'midnight', 0, 89),
('quote-322', 'The stillness of a pond reveals the sky above.', 'Lao Tzu', 'Mindfulness', '["pond", "reflection", "stillness"]', 'nordic', 0, 58),
('quote-323', 'Let your breath be your guide back to tranquility.', 'Jon Kabat-Zinn', 'Mindfulness', '["breath", "tranquility", "guide"]', 'sunset', 0, 70),
('quote-324', 'Simplicity of living produces richness of being.', 'E.F. Schumacher', 'Mindfulness', '["simplicity", "richness", "being"]', 'light', 0, 94),
('quote-325', 'In true listening, we offer the greatest gift of presence.', 'Thich Nhat Hanh', 'Mindfulness', '["listening", "gift", "presence"]', 'emerald', 0, 66),
('quote-326', 'Empty your cup so that it may be filled; become devoid to gain totality.', 'Bruce Lee', 'Mindfulness', '["empty-cup", "learning", "openness"]', 'midnight', 0, 44),
('quote-327', 'The greatest art is to sit quietly and do nothing.', 'Chinese Proverb', 'Mindfulness', '["art", "sitting", "wu-wei"]', 'nordic', 0, 91),
('quote-328', 'Allow each moment to unfold without resistance.', 'Eckhart Tolle', 'Mindfulness', '["unfolding", "flow", "non-resistance"]', 'sunset', 0, 138),
('quote-329', 'Your heartbeat is the ancient drum of life.', 'Alan Watts', 'Mindfulness', '["pulse", "rhythm", "life"]', 'light', 0, 105),
('quote-330', 'Look deeply into nature, and then you will understand everything better.', 'Albert Einstein', 'Mindfulness', '["nature", "insight", "understanding"]', 'emerald', 0, 47),
('quote-331', 'Peace is every step.', 'Thich Nhat Hanh', 'Mindfulness', '["step", "path", "everyday"]', 'midnight', 0, 41),
('quote-332', 'The mind is like water; when it is turbulent, it is difficult to see.', 'Sun Tzu', 'Mindfulness', '["water", "clarity", "vision"]', 'nordic', 0, 118),
('quote-333', 'Return to the breath, return to the center.', 'Pema Chödrön', 'Mindfulness', '["breath", "center", "refuge"]', 'sunset', 0, 104),
('quote-334', 'Nothing ever goes away until it has taught us what we need to know.', 'Pema Chödrön', 'Mindfulness', '["lessons", "patience", "growth"]', 'light', 0, 36),
('quote-335', 'You are the sky. Everything else is just the weather.', 'Pema Chödrön', 'Mindfulness', '["sky", "weather", "perspective"]', 'emerald', 0, 46),
('quote-336', 'Peace does not mean to be in a place where there is no noise; it means to be in the midst of those things and still be calm.', 'Anonymous', 'Mindfulness', '["calm", "noise", "resilience"]', 'midnight', 0, 131),
('quote-337', 'In the space between stimulus and response lies our growth and freedom.', 'Viktor Frankl', 'Mindfulness', '["space", "choice", "freedom"]', 'nordic', 0, 65),
('quote-338', 'Drop the idea of becoming someone, because you are already a masterpiece.', 'Osho', 'Mindfulness', '["acceptance", "masterpiece", "being"]', 'sunset', 0, 56),
('quote-339', 'The morning breeze has secrets to tell you. Do not go back to sleep.', 'Rumi', 'Mindfulness', '["breeze", "morning", "awakening"]', 'light', 0, 87),
('quote-340', 'Water does not resist. Water flows.', 'Margaret Atwood', 'Mindfulness', '["water", "flow", "yielding"]', 'emerald', 0, 97),
('quote-341', 'Walk as if you are kissing the Earth with your feet.', 'Thich Nhat Hanh', 'Mindfulness', '["earth", "gentle", "reverence"]', 'midnight', 0, 96),
('quote-342', 'Listen to the wind, it talks. Listen to the silence, it speaks.', 'Native American Proverb', 'Mindfulness', '["wind", "nature", "listening"]', 'nordic', 0, 62),
('quote-343', 'Be like a tree and let the dead leaves drop.', 'Rumi', 'Mindfulness', '["letting-go", "renewal", "nature"]', 'sunset', 0, 86),
('quote-344', 'Quiet minds cannot be perplexed or frightened, but go on in fortune or in misfortune at their own private pace.', 'Robert Louis Stevenson', 'Mindfulness', '["quiet-mind", "steadfast", "pace"]', 'light', 0, 42),
('quote-345', 'When you touch one thing with deep awareness, you touch everything.', 'Thich Nhat Hanh', 'Mindfulness', '["interconnection", "awareness", "depth"]', 'emerald', 0, 56),
('quote-346', 'The miracle is not to walk on water. The miracle is to walk on the green earth in the present moment.', 'Thich Nhat Hanh', 'Mindfulness', '["miracle", "earth", "presence"]', 'midnight', 0, 83),
('quote-347', 'Silence is the language of God, all else is poor translation.', 'Rumi', 'Mindfulness', '["silence", "divine", "language"]', 'nordic', 0, 35),
('quote-348', 'Give yourself permission to pause and breathe.', 'Jon Kabat-Zinn', 'Mindfulness', '["permission", "pause", "breathe"]', 'sunset', 0, 84),
('quote-349', 'The quieter you become, the more you can hear.', 'Ram Dass', 'Mindfulness', '["listening", "quiet", "hearing"]', 'light', 0, 68),
('quote-350', 'Every breath is a fresh start.', 'Anonymous', 'Mindfulness', '["breath", "fresh", "renewal"]', 'emerald', 0, 135),
('quote-351', 'In stillness, the answers you have been looking for will find you.', 'Anonymous', 'Mindfulness', '["stillness", "answers", "calm"]', 'midnight', 0, 135),
('quote-352', 'Release what you cannot control and cherish what you can.', 'Anonymous', 'Mindfulness', '["release", "cherish", "control"]', 'nordic', 0, 93),
('quote-353', 'Let your mind be as clear as an untroubled spring.', 'Anonymous', 'Mindfulness', '["clear", "spring", "purity"]', 'sunset', 0, 71),
('quote-354', 'There is a profound beauty in simply existing.', 'Anonymous', 'Mindfulness', '["existing", "beauty", "simplicity"]', 'light', 0, 89),
('quote-355', 'May your thoughts be gentle and your steps be peaceful.', 'Anonymous', 'Mindfulness', '["gentle", "peaceful", "blessing"]', 'emerald', 0, 124),
('quote-356', 'The lotus blossoms most beautifully from the deepest mud.', 'Buddhist Proverb', 'Mindfulness', '["lotus", "adversity", "beauty"]', 'midnight', 0, 128),
('quote-357', 'Listen to your breathing as if it were ocean waves upon a shore.', 'Anonymous', 'Mindfulness', '["breath", "ocean", "waves"]', 'nordic', 0, 135),
('quote-358', 'In the quietest hour of the night, find gratitude for having lived another day.', 'Anonymous', 'Mindfulness', '["gratitude", "night", "reflection"]', 'sunset', 0, 106),
('quote-359', 'Do not hurry, do not worry; you are exactly where you need to be.', 'Anonymous', 'Mindfulness', '["trust", "timing", "calm"]', 'light', 0, 119),
('quote-360', 'Breathe in courage, breathe out doubt.', 'Anonymous', 'Mindfulness', '["breath", "courage", "release"]', 'emerald', 0, 126),
('quote-361', 'The soul thrives in the garden of tranquility.', 'Anonymous', 'Mindfulness', '["garden", "tranquility", "thrive"]', 'midnight', 0, 97),
('quote-362', 'A peaceful heart makes a radiant face.', 'Proverbs', 'Mindfulness', '["radiance", "heart", "peace"]', 'nordic', 0, 54),
('quote-363', 'Find stillness in the breath and clarity in the mind.', 'Anonymous', 'Mindfulness', '["stillness", "breath", "clarity"]', 'sunset', 0, 59),
('quote-364', 'Every step taken with awareness is a step toward freedom.', 'Thich Nhat Hanh', 'Mindfulness', '["awareness", "step", "freedom"]', 'light', 0, 72),
('quote-365', 'Let go of the heavy load you were never meant to carry.', 'Anonymous', 'Mindfulness', '["lightness", "release", "burden"]', 'emerald', 0, 62),
('quote-366', 'Peace is not the absence of trouble, but the presence of grace.', 'Anonymous', 'Mindfulness', '["grace", "presence", "peace"]', 'midnight', 0, 42),
('quote-367', 'Rest your thoughts in the quiet space of your heart.', 'Anonymous', 'Mindfulness', '["heart", "rest", "quiet"]', 'nordic', 0, 109),
('quote-368', 'The morning light carries the promise of a peaceful day.', 'Anonymous', 'Mindfulness', '["morning", "light", "promise"]', 'sunset', 0, 129),
('quote-369', 'When you drink water, remember the spring.', 'Chinese Proverb', 'Mindfulness', '["gratitude", "source", "remembrance"]', 'light', 0, 104),
('quote-370', 'Be soft. Do not let the world make you hard.', 'Kurt Vonnegut', 'Mindfulness', '["softness", "gentleness", "heart"]', 'emerald', 0, 42),
('quote-371', 'Still waters reflect the majesty of the heavens.', 'Anonymous', 'Mindfulness', '["reflection", "majesty", "waters"]', 'midnight', 0, 130),
('quote-372', 'Embrace the quiet rhythm of your own unfolding.', 'Anonymous', 'Mindfulness', '["rhythm", "unfolding", "pace"]', 'nordic', 0, 75),
('quote-373', 'A single deep breath can change your entire day.', 'Anonymous', 'Mindfulness', '["breath", "change", "moment"]', 'sunset', 0, 42),
('quote-374', 'Plant seeds of kindness in the soil of tranquility.', 'Anonymous', 'Mindfulness', '["kindness", "tranquility", "seeds"]', 'light', 0, 41),
('quote-375', 'There is no river you cannot cross with patience and stillness.', 'Anonymous', 'Mindfulness', '["patience", "river", "stillness"]', 'emerald', 0, 109),
('quote-376', 'Let the dust settle before you seek your reflection.', 'Anonymous', 'Mindfulness', '["clarity", "settling", "reflection"]', 'midnight', 0, 96),
('quote-377', 'May you walk gently upon this sacred earth.', 'Anonymous', 'Mindfulness', '["sacred", "gentle", "earth"]', 'nordic', 0, 99),
('quote-378', 'Mindfulness is the art of befriending your own mind.', 'Jon Kabat-Zinn', 'Mindfulness', '["friendship", "mind", "art"]', 'sunset', 0, 102),
('quote-379', 'In every season of life, peace is a choice you can make.', 'Anonymous', 'Mindfulness', '["choice", "peace", "seasons"]', 'light', 0, 55),
('quote-380', 'Breathe in peace, exhale tension.', 'Anonymous', 'Mindfulness', '["breath", "release", "peace"]', 'emerald', 0, 42),
('quote-381', 'Your presence is your greatest power.', 'Anonymous', 'Mindfulness', '["presence", "power", "now"]', 'midnight', 0, 100),
('quote-382', 'Stillness is where your spirit gathers strength.', 'Anonymous', 'Mindfulness', '["stillness", "spirit", "strength"]', 'nordic', 0, 45),
('quote-383', 'When the mind is peaceful, the world is at rest.', 'Anonymous', 'Mindfulness', '["peaceful", "world", "rest"]', 'sunset', 0, 58),
('quote-384', 'Allow your heart to be open like the morning sky.', 'Anonymous', 'Mindfulness', '["sky", "open-heart", "morning"]', 'light', 0, 43),
('quote-385', 'Treasures of the soul are found only in the silence.', 'Anonymous', 'Mindfulness', '["treasures", "soul", "silence"]', 'emerald', 0, 111),
('quote-386', 'Observe the river of time without rushing into the current.', 'Anonymous', 'Mindfulness', '["river", "observation", "time"]', 'midnight', 0, 43),
('quote-387', 'Every sunset is an invitation to pause and reflect.', 'Anonymous', 'Mindfulness', '["sunset", "pause", "reflection"]', 'nordic', 0, 121),
('quote-388', 'May peace be your shield and kindness your guide.', 'Anonymous', 'Mindfulness', '["shield", "kindness", "peace"]', 'sunset', 0, 65),
('quote-389', 'The greatest journey begins with a single mindful breath.', 'Anonymous', 'Mindfulness', '["journey", "breath", "beginning"]', 'light', 0, 86),
('quote-390', 'Find harmony between doing and simply being.', 'Anonymous', 'Mindfulness', '["harmony", "being", "doing"]', 'emerald', 0, 50),
('quote-391', 'Quiet your doubts and trust the wisdom of your breath.', 'Anonymous', 'Mindfulness', '["trust", "wisdom", "breath"]', 'midnight', 0, 107),
('quote-392', 'Light your inner lamp and darkness will vanish.', 'Buddha', 'Mindfulness', '["inner-light", "lamp", "wisdom"]', 'nordic', 0, 66),
('quote-393', 'Let your spirit rest in the calm ocean of Being.', 'Anonymous', 'Mindfulness', '["ocean", "spirit", "being"]', 'sunset', 0, 109),
('quote-394', 'The unexamined life is not worth living.', 'Socrates', 'Philosophy', '["examination", "self-knowledge", "truth"]', 'light', 0, 111),
('quote-395', 'I think, therefore I am.', 'René Descartes', 'Philosophy', '["existence", "thought", "foundation"]', 'emerald', 0, 40),
('quote-396', 'He who has a why to live can bear almost any how.', 'Friedrich Nietzsche', 'Philosophy', '["meaning", "resilience", "purpose"]', 'midnight', 0, 114),
('quote-397', 'Man is condemned to be free; because once thrown into the world, he is responsible for everything he does.', 'Jean-Paul Sartre', 'Philosophy', '["freedom", "responsibility", "existentialism"]', 'nordic', 0, 45),
('quote-398', 'We are what we repeatedly do. Excellence, then, is not an act, but a habit.', 'Aristotle', 'Philosophy', '["habit", "excellence", "discipline"]', 'sunset', 0, 88),
('quote-399', 'Entities should not be multiplied unnecessarily.', 'William of Ockham', 'Philosophy', '["simplicity", "reasoning", "clarity"]', 'light', 0, 119),
('quote-400', 'Happiness is the meaning and the purpose of life, the whole aim and end of human existence.', 'Aristotle', 'Philosophy', '["happiness", "eudaimonia", "purpose"]', 'emerald', 0, 109)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-401', 'To know, is to know that you know nothing. That is the meaning of true knowledge.', 'Socrates', 'Philosophy', '["humility", "wisdom", "learning"]', 'midnight', 0, 107),
('quote-402', 'Life must be understood backward. But it must be lived forward.', 'Søren Kierkegaard', 'Philosophy', '["time", "understanding", "forward"]', 'nordic', 0, 101),
('quote-403', 'There is only one really serious philosophical problem, and that is suicide. Deciding whether or not life is worth living is to answer the fundamental question in philosophy.', 'Albert Camus', 'Philosophy', '["meaning", "absurdism", "life"]', 'sunset', 0, 75),
('quote-404', 'You can discover more about a person in an hour of play than in a year of conversation.', 'Plato', 'Philosophy', '["play", "character", "human-nature"]', 'light', 0, 68),
('quote-405', 'I cannot teach anybody anything. I can only make them think.', 'Socrates', 'Philosophy', '["education", "questioning", "curiosity"]', 'emerald', 0, 61),
('quote-406', 'In the midst of winter, I found there was, within me, an invincible summer.', 'Albert Camus', 'Philosophy', '["resilience", "inner-strength", "hope"]', 'midnight', 0, 120),
('quote-407', 'The only thing I know is that I know nothing.', 'Socrates', 'Philosophy', '["humility", "paradox", "knowledge"]', 'nordic', 0, 126),
('quote-408', 'Liberty consists in doing what one desires.', 'John Stuart Mill', 'Philosophy', '["liberty", "desire", "freedom"]', 'sunset', 0, 75),
('quote-409', 'Wonder is the feeling of a philosopher, and philosophy begins in wonder.', 'Plato', 'Philosophy', '["wonder", "curiosity", "origins"]', 'light', 0, 65),
('quote-410', 'God is dead. God remains dead. And we have killed him. How shall we comfort ourselves, the murderers of all murderers?', 'Friedrich Nietzsche', 'Philosophy', '["culture", "modernity", "critique"]', 'emerald', 0, 68),
('quote-411', 'The brave man is he who overcomes not only his enemies, but his pleasures.', 'Democritus', 'Philosophy', '["self-control", "pleasure", "bravery"]', 'midnight', 0, 85),
('quote-412', 'He who knows others is wise; he who knows himself is enlightened.', 'Lao Tzu', 'Philosophy', '["enlightenment", "self-awareness", "wisdom"]', 'nordic', 0, 51),
('quote-413', 'Anxiety is the dizziness of freedom.', 'Søren Kierkegaard', 'Philosophy', '["anxiety", "freedom", "choice"]', 'sunset', 0, 120),
('quote-414', 'Those who can make you believe absurdities can make you commit atrocities.', 'Voltaire', 'Philosophy', '["critical-thinking", "reason", "justice"]', 'light', 0, 117),
('quote-415', 'To be is to be perceived.', 'George Berkeley', 'Philosophy', '["perception", "reality", "mind"]', 'emerald', 0, 73),
('quote-416', 'Custom is the great guide of human life.', 'David Hume', 'Philosophy', '["habit", "human-nature", "custom"]', 'midnight', 0, 93),
('quote-417', 'Man is born free, and everywhere he is in chains.', 'Jean-Jacques Rousseau', 'Philosophy', '["society", "freedom", "politics"]', 'nordic', 0, 75),
('quote-418', 'All that is real is rational, and all that is rational is real.', 'G.W.F. Hegel', 'Philosophy', '["dialectic", "rationality", "reality"]', 'sunset', 0, 131),
('quote-419', 'History repeats itself, first as tragedy, second as farce.', 'Karl Marx', 'Philosophy', '["history", "cycles", "critique"]', 'light', 0, 44),
('quote-420', 'Science is what you know. Philosophy is what you don''t know.', 'Bertrand Russell', 'Philosophy', '["science", "philosophy", "curiosity"]', 'emerald', 0, 36),
('quote-421', 'The greatest happiness of the greatest number is the foundation of morals and legislation.', 'Jeremy Bentham', 'Philosophy', '["utilitarianism", "ethics", "society"]', 'midnight', 0, 93),
('quote-422', 'The limits of my language mean the limits of my world.', 'Ludwig Wittgenstein', 'Philosophy', '["language", "world", "thought"]', 'nordic', 0, 114),
('quote-423', 'Whereof one cannot speak, thereof one must be silent.', 'Ludwig Wittgenstein', 'Philosophy', '["silence", "truth", "limits"]', 'sunset', 0, 107),
('quote-424', 'Nothing exists except atoms and empty space; everything else is opinion.', 'Democritus', 'Philosophy', '["atomism", "reality", "materialism"]', 'light', 0, 47),
('quote-425', 'It is the mark of an educated mind to be able to entertain a thought without accepting it.', 'Aristotle', 'Philosophy', '["critical-thinking", "open-mindedness", "intellect"]', 'emerald', 0, 44),
('quote-426', 'To live is to suffer, to survive is to find some meaning in the suffering.', 'Friedrich Nietzsche', 'Philosophy', '["survival", "meaning", "suffering"]', 'midnight', 0, 103),
('quote-427', 'The soul is dyed the color of its thoughts.', 'Heraclitus', 'Philosophy', '["thoughts", "soul", "character"]', 'nordic', 0, 62),
('quote-428', 'No man ever steps in the same river twice, for it''s not the same river and he''s not the same man.', 'Heraclitus', 'Philosophy', '["change", "impermanence", "flux"]', 'sunset', 0, 99),
('quote-429', 'Everything flows, nothing stands still.', 'Heraclitus', 'Philosophy', '["flux", "change", "nature"]', 'light', 0, 68),
('quote-430', 'The mind is furnished with ideas by experience alone.', 'John Locke', 'Philosophy', '["empiricism", "experience", "learning"]', 'emerald', 0, 51),
('quote-431', 'We do not describe the world we see, we see the world we can describe.', 'René Descartes', 'Philosophy', '["perception", "language", "cognition"]', 'midnight', 0, 79),
('quote-432', 'Dare to know! Have the courage to use your own understanding.', 'Immanuel Kant', 'Philosophy', '["enlightenment", "courage", "reason"]', 'nordic', 0, 43),
('quote-433', 'Act only according to that maxim whereby you can, at the same time, will that it should become a universal law.', 'Immanuel Kant', 'Philosophy', '["duty", "universal-law", "ethics"]', 'sunset', 0, 66),
('quote-434', 'Two things awe me most, the starry sky above me and the moral law within me.', 'Immanuel Kant', 'Philosophy', '["cosmos", "morality", "awe"]', 'light', 0, 82),
('quote-435', 'He who fights with monsters should look to it that he himself does not become a monster.', 'Friedrich Nietzsche', 'Philosophy', '["vigilance", "morality", "shadow"]', 'emerald', 0, 71),
('quote-436', 'And if you gaze long into an abyss, the abyss also gazes into you.', 'Friedrich Nietzsche', 'Philosophy', '["abyss", "depth", "introspection"]', 'midnight', 0, 55),
('quote-437', 'One cannot step twice into the same waters.', 'Heraclitus', 'Philosophy', '["impermanence", "presence", "flow"]', 'nordic', 0, 91),
('quote-438', 'The price good men pay for indifference to public affairs is to be ruled by evil men.', 'Plato', 'Philosophy', '["civics", "duty", "justice"]', 'sunset', 0, 104),
('quote-439', 'Wise men speak because they have something to say; fools because they have to say something.', 'Plato', 'Philosophy', '["wisdom", "discernment", "speech"]', 'light', 0, 125),
('quote-440', 'Courage is knowing what not to fear.', 'Plato', 'Philosophy', '["courage", "wisdom", "fear"]', 'emerald', 0, 73),
