('quote-444', 'Knowing yourself is the beginning of all wisdom.', 'Aristotle', 'Philosophy', '["self-awareness", "origins", "wisdom"]', 'light', 0, 102),
('quote-445', 'Patience is bitter, but its fruit is sweet.', 'Aristotle', 'Philosophy', '["patience", "virtue", "reward"]', 'emerald', 0, 36),
('quote-446', 'To perceive is to suffer.', 'Aristotle', 'Philosophy', '["perception", "sensitivity", "existence"]', 'midnight', 0, 120),
('quote-447', 'Hope is a waking dream.', 'Aristotle', 'Philosophy', '["hope", "dreams", "imagination"]', 'nordic', 0, 139),
