('quote-452', 'Live in the sunshine, swim the sea, drink the wild air.', 'Ralph Waldo Emerson', 'Philosophy', '["nature", "vitality", "wild"]', 'nordic', 0, 52),
('quote-453', 'The invariable mark of wisdom is to see the miraculous in the common.', 'Ralph Waldo Emerson', 'Philosophy', '["miracles", "everyday", "wisdom"]', 'sunset', 0, 68),
('quote-454', 'I went to the woods because I wished to live deliberately.', 'Henry David Thoreau', 'Philosophy', '["deliberate", "nature", "solitude"]', 'light', 0, 49),
('quote-455', 'Rather than love, than money, than fame, give me truth.', 'Henry David Thoreau', 'Philosophy', '["truth", "integrity", "values"]', 'emerald', 0, 48),
('quote-456', 'Things do not change; we change.', 'Henry David Thoreau', 'Philosophy', '["growth", "perception", "transformation"]', 'midnight', 0, 130),
