('quote-461', 'Not all those who wander are lost.', 'J.R.R. Tolkien', 'Philosophy', '["wandering", "journey", "exploration"]', 'midnight', 0, 112),
('quote-462', 'Without music, life would be a mistake.', 'Friedrich Nietzsche', 'Philosophy', '["music", "art", "life"]', 'nordic', 0, 61),
('quote-463', 'The higher we soar the smaller we appear to those who cannot fly.', 'Friedrich Nietzsche', 'Philosophy', '["elevation", "perspective", "growth"]', 'sunset', 0, 126),
('quote-464', 'You must have chaos within you to give birth to a dancing star.', 'Friedrich Nietzsche', 'Philosophy', '["chaos", "creation", "genius"]', 'light', 0, 78),
('quote-465', 'There are no facts, only interpretations.', 'Friedrich Nietzsche', 'Philosophy', '["perspective", "relativism", "truth"]', 'emerald', 0, 61),
('quote-466', 'That which does not kill us makes us stronger.', 'Friedrich Nietzsche', 'Philosophy', '["strength", "resilience", "adversity"]', 'midnight', 0, 122),
('quote-467', 'In every real man a child is hidden that wants to play.', 'Friedrich Nietzsche', 'Philosophy', '["inner-child", "play", "authenticity"]', 'nordic', 0, 116),
('quote-468', 'Become who you are.', 'Friedrich Nietzsche', 'Philosophy', '["becoming", "potential", "destiny"]', 'sunset', 0, 68),
