('quote-486', 'Self-knowledge is the beginning of wisdom.', 'Plato', 'Philosophy', '["self-knowledge", "wisdom", "foundation"]', 'midnight', 0, 91),
('quote-487', 'A system of morality which is based on relative emotional values is a mere illusion.', 'Socrates', 'Philosophy', '["morality", "ethics", "truth"]', 'nordic', 0, 105),
('quote-488', 'False words are not only evil in themselves, but they infect the soul with evil.', 'Plato', 'Philosophy', '["truthfulness", "speech", "integrity"]', 'sunset', 0, 125),
('quote-489', 'There is no harm in repeating a good thing.', 'Plato', 'Philosophy', '["repetition", "goodness", "virtue"]', 'light', 0, 89),
('quote-490', 'Only the dead have seen the end of war.', 'George Santayana', 'Philosophy', '["peace", "history", "war"]', 'emerald', 0, 106),
('quote-491', 'Those who cannot remember the past are condemned to repeat it.', 'George Santayana', 'Philosophy', '["memory", "history", "wisdom"]', 'midnight', 0, 36),
