INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-501', 'Iron rusts from disuse; water loses its purity from stagnation... even so does inaction sap the vigor of the mind.', 'Leonardo da Vinci', 'Philosophy', '["action", "vigor", "mind"]', 'midnight', 0, 53),
