('quote-552', 'Life is really simple, but we insist on making it complicated.', 'Confucius', 'Wisdom', '["simplicity", "clarity", "life"]', 'nordic', 0, 74),
('quote-553', 'A gentle answer turns away wrath, but a harsh word stirs up anger.', 'Proverbs', 'Wisdom', '["gentleness", "wrath", "peace"]', 'sunset', 0, 140),
('quote-554', 'As water reflects the face, so one''s life reflects the heart.', 'Proverbs', 'Wisdom', '["reflection", "heart", "integrity"]', 'light', 0, 136),
