('quote-564', 'You cannot direct the wind, but you can adjust your sails.', 'Dolly Parton', 'Wisdom', '["adaptability", "control", "navigation"]', 'light', 0, 133),
('quote-565', 'Honesty is the first chapter in the book of wisdom.', 'Thomas Jefferson', 'Wisdom', '["honesty", "wisdom", "integrity"]', 'emerald', 0, 70),
('quote-566', 'The only true wisdom is in knowing you know nothing.', 'Socrates', 'Wisdom', '["humility", "truth", "wisdom"]', 'midnight', 0, 79),
