('quote-569', 'The time is always right to do what is right.', 'Martin Luther King Jr.', 'Wisdom', '["justice", "right-action", "timing"]', 'light', 0, 86),
('quote-570', 'Darkness cannot drive out darkness; only light can do that. Hate cannot drive out hate; only love can do that.', 'Martin Luther King Jr.', 'Wisdom', '["light", "love", "nonviolence"]', 'emerald', 0, 121),
