('quote-574', 'Life''s most persistent and urgent question is: ''What are you doing for others?''', 'Martin Luther King Jr.', 'Wisdom', '["service", "compassion", "duty"]', 'light', 0, 49),
('quote-575', 'Forgiveness is not an occasional act; it is a constant attitude.', 'Martin Luther King Jr.', 'Wisdom', '["forgiveness", "attitude", "peace"]', 'emerald', 0, 68),
