('quote-582', 'The only way to do great work is to love what you do.', 'Steve Jobs', 'Wisdom', '["passion", "work", "excellence"]', 'nordic', 0, 90),
('quote-583', 'Stay hungry, stay foolish.', 'Steve Jobs', 'Wisdom', '["curiosity", "humility", "ambition"]', 'sunset', 0, 79),
