('quote-588', 'Details matter, it''s worth waiting to get it right.', 'Steve Jobs', 'Wisdom', '["craft", "details", "patience"]', 'sunset', 0, 112),
('quote-589', 'I would rather bet on our vision than build a me-too product.', 'Steve Jobs', 'Wisdom', '["vision", "originality", "boldness"]', 'light', 0, 100),
('quote-590', 'Sometimes when you innovate, you make mistakes. It is best to admit them quickly, and get on with improving your other innovations.', 'Steve Jobs', 'Wisdom', '["innovation", "mistakes", "agility"]', 'emerald', 0, 49),
('quote-591', 'Remembering that you are going to die is the best way I know to avoid the trap of thinking you have something to lose.', 'Steve Jobs', 'Wisdom', '["mortality", "courage", "boldness"]', 'midnight', 0, 84),
('quote-592', 'Be a yardstick of quality. Some people aren''t used to an environment where excellence is expected.', 'Steve Jobs', 'Wisdom', '["quality", "standards", "excellence"]', 'nordic', 0, 108),
('quote-593', 'What we think, we become.', 'Buddha', 'Wisdom', '["mind", "becoming", "thoughts"]', 'sunset', 0, 59),
('quote-594', 'All that we are is the result of what we have thought.', 'Buddha', 'Wisdom', '["mindset", "creation", "reality"]', 'light', 0, 67),
('quote-595', 'Radiate boundless love towards the entire world.', 'Buddha', 'Wisdom', '["metta", "boundless", "love"]', 'emerald', 0, 40),
('quote-596', 'Health is the greatest gift, contentment the greatest wealth, faithfulness the best relationship.', 'Buddha', 'Wisdom', '["health", "contentment", "faithfulness"]', 'midnight', 0, 125),
('quote-597', 'Three things cannot be long hidden: the sun, the moon, and the truth.', 'Buddha', 'Wisdom', '["truth", "sun", "inevitable"]', 'nordic', 0, 90),
('quote-598', 'Purity or impurity depends on oneself, No one can purify another.', 'Buddha', 'Wisdom', '["responsibility", "purity", "self"]', 'sunset', 0, 35),
('quote-599', 'No one saves us but ourselves. No one can and no one may. We ourselves must walk the path.', 'Buddha', 'Wisdom', '["self-reliance", "path", "liberation"]', 'light', 0, 101),
('quote-600', 'Chaos gives birth to stars.', 'Anonymous', 'Wisdom', '["chaos", "stars", "creation"]', 'emerald', 0, 138)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-601', 'The cave you fear to enter holds the treasure you seek.', 'Joseph Campbell', 'Wisdom', '["courage", "treasure", "hero''s-journey"]', 'midnight', 0, 103),
('quote-602', 'Follow your bliss and the universe will open doors for you where there were only walls.', 'Joseph Campbell', 'Wisdom', '["bliss", "destiny", "doors"]', 'nordic', 0, 122),
('quote-603', 'We must let go of the life we have planned, so as to accept the one that is waiting for us.', 'Joseph Campbell', 'Wisdom', '["acceptance", "surrender", "unfolding"]', 'sunset', 0, 127),
('quote-604', 'The privilege of a lifetime is being who you are.', 'Joseph Campbell', 'Wisdom', '["authenticity", "privilege", "self"]', 'light', 0, 129),
('quote-605', 'Find a place inside where there''s joy, and the joy will burn out the pain.', 'Joseph Campbell', 'Wisdom', '["joy", "inner-depth", "healing"]', 'emerald', 0, 129),
('quote-606', 'Participate joyfully in the sorrows of the world.', 'Joseph Campbell', 'Wisdom', '["compassion", "joy", "world"]', 'midnight', 0, 120),
('quote-607', 'Opportunities multiply as they are seized.', 'Sun Tzu', 'Wisdom', '["momentum", "opportunity", "action"]', 'nordic', 0, 60),
('quote-608', 'He will win who knows when to fight and when not to fight.', 'Sun Tzu', 'Wisdom', '["discernment", "strategy", "restraint"]', 'sunset', 0, 81),
('quote-609', 'In the midst of chaos, there is also opportunity.', 'Sun Tzu', 'Wisdom', '["chaos", "opportunity", "strategy"]', 'light', 0, 90),
('quote-610', 'Pretend inferiority and encourage his arrogance.', 'Sun Tzu', 'Wisdom', '["humility", "tactics", "insight"]', 'emerald', 0, 43),
('quote-611', 'There is no instance of a nation benefitting from prolonged warfare.', 'Sun Tzu', 'Wisdom', '["peace", "warfare", "wisdom"]', 'midnight', 0, 120),
('quote-612', 'Great results, can be achieved with small forces.', 'Sun Tzu', 'Wisdom', '["leverage", "strategy", "efficiency"]', 'nordic', 0, 77),
('quote-613', 'Patience is the companion of wisdom.', 'Saint Augustine', 'Wisdom', '["patience", "wisdom", "virtue"]', 'sunset', 0, 114),
('quote-614', 'The world is a book and those who do not travel read only one page.', 'Saint Augustine', 'Wisdom', '["travel", "perspective", "exploration"]', 'light', 0, 75),
('quote-615', 'Hope has two beautiful daughters; their names are Anger and Courage.', 'Saint Augustine', 'Wisdom', '["hope", "courage", "transformation"]', 'emerald', 0, 119),
('quote-616', 'Order your soul; reduce your wants; live in charity; associate with the good.', 'Saint Augustine', 'Wisdom', '["order", "charity", "simplicity"]', 'midnight', 0, 50),
('quote-617', 'Trust the process of life, even when the road is steep.', 'Anonymous', 'Wisdom', '["trust", "process", "resilience"]', 'nordic', 0, 127),
('quote-618', 'The way to get started is to quit talking and begin doing.', 'Walt Disney', 'Motivation', '["action", "start", "doing"]', 'sunset', 0, 73),
('quote-619', 'If you can dream it, you can do it.', 'Walt Disney', 'Motivation', '["dreams", "possibility", "belief"]', 'light', 0, 99),
('quote-620', 'All our dreams can come true, if we have the courage to pursue them.', 'Walt Disney', 'Motivation', '["courage", "pursuit", "dreams"]', 'emerald', 0, 74),
('quote-621', 'It''s kind of fun to do the impossible.', 'Walt Disney', 'Motivation', '["impossible", "fun", "ambition"]', 'midnight', 0, 120),
('quote-622', 'The difference in winning and losing is most often not quitting.', 'Walt Disney', 'Motivation', '["persistence", "winning", "perseverance"]', 'nordic', 0, 87),
('quote-623', 'Whether you think you can or you think you can''t, you''re right.', 'Henry Ford', 'Motivation', '["mindset", "belief", "confidence"]', 'sunset', 0, 76),
('quote-624', 'Don''t find fault, find a remedy; anybody can complain.', 'Henry Ford', 'Motivation', '["solutions", "focus", "initiative"]', 'light', 0, 86),
('quote-625', 'Failure is simply the opportunity to begin again, this time more intelligently.', 'Henry Ford', 'Motivation', '["failure", "intelligence", "restart"]', 'emerald', 0, 124),
('quote-626', 'Coming together is a beginning; keeping together is progress; working together is success.', 'Henry Ford', 'Motivation', '["teamwork", "collaboration", "progress"]', 'midnight', 0, 72),
('quote-627', 'Obstacles are those frightful things you see when you take your eyes off your goal.', 'Henry Ford', 'Motivation', '["focus", "goals", "obstacles"]', 'nordic', 0, 105),
('quote-628', 'You can''t build a reputation on what you are going to do.', 'Henry Ford', 'Motivation', '["action", "reputation", "execution"]', 'sunset', 0, 51),
('quote-629', 'I have not failed. I''ve just found 10,000 ways that won''t work.', 'Thomas Edison', 'Motivation', '["experimentation", "persistence", "inquiry"]', 'light', 0, 59),
('quote-630', 'Genius is one percent inspiration and ninety-nine percent perspiration.', 'Thomas Edison', 'Motivation', '["effort", "hard-work", "genius"]', 'emerald', 0, 88),
('quote-631', 'Our greatest weakness lies in giving up. The most certain way always to succeed is just to try one more time.', 'Thomas Edison', 'Motivation', '["persistence", "resilience", "trying"]', 'midnight', 0, 120),
('quote-632', 'Opportunity is missed by most people because it is dressed in overalls and looks like work.', 'Thomas Edison', 'Motivation', '["opportunity", "work-ethic", "diligence"]', 'nordic', 0, 83),
('quote-633', 'If we did all the things we are capable of, we would literally astound ourselves.', 'Thomas Edison', 'Motivation', '["capability", "potential", "wonder"]', 'sunset', 0, 121),
('quote-634', 'There is no substitute for hard work.', 'Thomas Edison', 'Motivation', '["hard-work", "dedication", "discipline"]', 'light', 0, 130),
('quote-635', 'Action is the foundational key to all success.', 'Pablo Picasso', 'Motivation', '["action", "foundation", "success"]', 'emerald', 0, 57),
('quote-636', 'I am always doing that which I cannot do, in order that I may learn how to do it.', 'Pablo Picasso', 'Motivation', '["learning", "growth", "challenge"]', 'midnight', 0, 113),
('quote-637', 'Inspiration exists, but it has to find you working.', 'Pablo Picasso', 'Motivation', '["inspiration", "craft", "work"]', 'nordic', 0, 107),
('quote-638', 'Only put off until tomorrow what you are willing to die having left undone.', 'Pablo Picasso', 'Motivation', '["urgency", "purpose", "action"]', 'sunset', 0, 73),
('quote-639', 'Everything you can imagine is real.', 'Pablo Picasso', 'Motivation', '["imagination", "reality", "creation"]', 'light', 0, 86),
('quote-640', 'It always seems impossible until it''s done.', 'Nelson Mandela', 'Motivation', '["impossible", "achievement", "hope"]', 'emerald', 0, 105),
('quote-641', 'A winner is a dreamer who never gives up.', 'Nelson Mandela', 'Motivation', '["dreams", "perseverance", "winning"]', 'midnight', 0, 35),
('quote-642', 'After climbing a great hill, one only finds that there are many more hills to climb.', 'Nelson Mandela', 'Motivation', '["journey", "humility", "growth"]', 'nordic', 0, 73),
('quote-643', 'Do not judge me by my successes, judge me by how many times I fell down and got back up again.', 'Nelson Mandela', 'Motivation', '["resilience", "character", "perseverance"]', 'sunset', 0, 71),
('quote-644', 'There is no passion to be found playing small — in settling for a life that is less than the one you are capable of living.', 'Nelson Mandela', 'Motivation', '["passion", "ambition", "potential"]', 'light', 0, 61),
('quote-645', 'Success is not final, failure is not fatal: it is the courage to continue that counts.', 'Winston Churchill', 'Motivation', '["courage", "continuing", "success"]', 'emerald', 0, 90),
('quote-646', 'If you are going through hell, keep going.', 'Winston Churchill', 'Motivation', '["grit", "perseverance", "toughness"]', 'midnight', 0, 135),
('quote-647', 'Attitude is a little thing that makes a big difference.', 'Winston Churchill', 'Motivation', '["attitude", "perspective", "power"]', 'nordic', 0, 109),
('quote-648', 'To improve is to change; to be perfect is to change often.', 'Winston Churchill', 'Motivation', '["change", "improvement", "growth"]', 'sunset', 0, 112),
('quote-649', 'Never, never, never give up.', 'Winston Churchill', 'Motivation', '["relentless", "grit", "never-give-up"]', 'light', 0, 118),
('quote-650', 'Continuous effort — not strength or intelligence — is the key to unlocking our potential.', 'Winston Churchill', 'Motivation', '["effort", "potential", "keys"]', 'emerald', 0, 76),
('quote-651', 'A pessimist sees the difficulty in every opportunity; an optimist sees the opportunity in every difficulty.', 'Winston Churchill', 'Motivation', '["optimism", "perspective", "mindset"]', 'midnight', 0, 94),
('quote-652', 'We make a living by what we get, but we make a life by what we give.', 'Winston Churchill', 'Motivation', '["generosity", "giving", "life"]', 'nordic', 0, 91),
('quote-653', 'I am an optimist. It does not seem too much use being anything else.', 'Winston Churchill', 'Motivation', '["optimism", "pragmatism", "cheer"]', 'sunset', 0, 91),
('quote-654', 'Success usually comes to those who are too busy to be looking for it.', 'Henry David Thoreau', 'Motivation', '["focus", "diligence", "flow"]', 'light', 0, 121),
('quote-655', 'The secret of getting ahead is getting started.', 'Mark Twain', 'Motivation', '["beginnings", "action", "momentum"]', 'emerald', 0, 62),
('quote-656', 'Twenty years from now you will be more disappointed by the things that you didn''t do than by the ones you did do.', 'Mark Twain', 'Motivation', '["boldness", "regret", "action"]', 'midnight', 0, 100),
('quote-657', 'Sail away from the safe harbor. Catch the trade winds in your sails. Explore. Dream. Discover.', 'Mark Twain', 'Motivation', '["exploration", "adventure", "dreams"]', 'nordic', 0, 95),
('quote-658', 'Continuous improvement is better than delayed perfection.', 'Mark Twain', 'Motivation', '["iteration", "progress", "action"]', 'sunset', 0, 136),
('quote-659', 'Courage is resistance to fear, mastery of fear — not absence of fear.', 'Mark Twain', 'Motivation', '["courage", "fear", "mastery"]', 'light', 0, 136),
('quote-660', 'Don''t count the days, make the days count.', 'Muhammad Ali', 'Motivation', '["presence", "impact", "daily"]', 'emerald', 0, 129),
('quote-661', 'I hated every minute of training, but I said, ''Don''t quit. Suffer now and live the rest of your life as a champion.''', 'Muhammad Ali', 'Motivation', '["sacrifice", "training", "champion"]', 'midnight', 0, 56),
('quote-662', 'He who is not courageous enough to take risks will accomplish nothing in life.', 'Muhammad Ali', 'Motivation', '["risk", "courage", "accomplishment"]', 'nordic', 0, 119),
('quote-663', 'Champions aren''t made in gyms. Champions are made from something they have deep inside them: a desire, a dream, a vision.', 'Muhammad Ali', 'Motivation', '["heart", "vision", "desire"]', 'sunset', 0, 45),
('quote-664', 'Impossible is not a fact. It''s an opinion. Impossible is potential. Impossible is temporary. Impossible is nothing.', 'Muhammad Ali', 'Motivation', '["impossible", "potential", "greatness"]', 'light', 0, 71),
('quote-665', 'You miss 100% of the shots you don''t take.', 'Wayne Gretzky', 'Motivation', '["initiative", "risk", "action"]', 'emerald', 0, 100),
('quote-666', 'I''ve failed over and over and over again in my life. And that is why I succeed.', 'Michael Jordan', 'Motivation', '["failure", "resilience", "success"]', 'midnight', 0, 119),
('quote-667', 'Talent wins games, but teamwork and intelligence win championships.', 'Michael Jordan', 'Motivation', '["teamwork", "intelligence", "excellence"]', 'nordic', 0, 116),
('quote-668', 'Some people want it to happen, some wish it would happen, others make it happen.', 'Michael Jordan', 'Motivation', '["initiative", "drive", "execution"]', 'sunset', 0, 114),
('quote-669', 'If you quit once it becomes a habit. Never quit!', 'Michael Jordan', 'Motivation', '["relentless", "habit", "grit"]', 'light', 0, 77),
('quote-670', 'Obstacles don''t have to stop you. If you run into a wall, don''t turn around and give up. Figure out how to climb it.', 'Michael Jordan', 'Motivation', '["problem-solving", "walls", "determination"]', 'emerald', 0, 46),
('quote-671', 'Hard work beats talent when talent doesn''t work hard.', 'Tim Notke', 'Motivation', '["work-ethic", "discipline", "humility"]', 'midnight', 0, 139),
('quote-672', 'The future belongs to those who believe in the beauty of their dreams.', 'Eleanor Roosevelt', 'Motivation', '["dreams", "future", "belief"]', 'nordic', 0, 131),
('quote-673', 'Do one thing every day that scares you.', 'Eleanor Roosevelt', 'Motivation', '["courage", "growth", "comfort-zone"]', 'sunset', 0, 65),
('quote-674', 'No one can make you feel inferior without your consent.', 'Eleanor Roosevelt', 'Motivation', '["dignity", "boundaries", "self-worth"]', 'light', 0, 121),
('quote-675', 'You must do the things you think you cannot do.', 'Eleanor Roosevelt', 'Motivation', '["breakthrough", "courage", "stretch"]', 'emerald', 0, 74),
('quote-676', 'With the new day comes new strength and new thoughts.', 'Eleanor Roosevelt', 'Motivation', '["dawn", "renewal", "strength"]', 'midnight', 0, 63),
('quote-677', 'Great minds discuss ideas; average minds discuss events; small minds discuss people.', 'Eleanor Roosevelt', 'Motivation', '["mindset", "conversations", "intellect"]', 'nordic', 0, 138),
('quote-678', 'It is better to light a candle than curse the darkness.', 'Eleanor Roosevelt', 'Motivation', '["action", "solutions", "light"]', 'sunset', 0, 60),
('quote-679', 'The only limit to our realization of tomorrow will be our doubts of today.', 'Franklin D. Roosevelt', 'Motivation', '["doubt", "limitless", "tomorrow"]', 'light', 0, 53),
('quote-680', 'When you reach the end of your rope, tie a knot in it and hang on.', 'Franklin D. Roosevelt', 'Motivation', '["endurance", "perseverance", "hope"]', 'emerald', 0, 38),
('quote-681', 'Believe you can and you''re halfway there.', 'Theodore Roosevelt', 'Motivation', '["belief", "confidence", "momentum"]', 'midnight', 0, 40),
('quote-682', 'Keep your eyes on the stars, and your feet on the ground.', 'Theodore Roosevelt', 'Motivation', '["vision", "practicality", "balance"]', 'nordic', 0, 66),
('quote-683', 'It is hard to fail, but it is worse never to have tried to succeed.', 'Theodore Roosevelt', 'Motivation', '["effort", "courage", "trying"]', 'sunset', 0, 95),
('quote-684', 'Do what you can, with what you have, where you are.', 'Theodore Roosevelt', 'Motivation', '["resourcefulness", "pragmatism", "action"]', 'light', 0, 113),
('quote-685', 'Far and away the best prize that life has to offer is the chance to work hard at work worth doing.', 'Theodore Roosevelt', 'Motivation', '["work-ethic", "purpose", "meaning"]', 'emerald', 0, 133),
('quote-686', 'The man who really counts in the world is the doer, not the man who merely sits by and says how a thing ought to be done.', 'Theodore Roosevelt', 'Motivation', '["doer", "action", "critics"]', 'midnight', 0, 44),
('quote-687', 'Courage is not having the strength to go on; it is going on when you don''t have the strength.', 'Theodore Roosevelt', 'Motivation', '["courage", "grit", "resilience"]', 'nordic', 0, 93),
('quote-688', 'In any moment of decision, the best thing you can do is the right thing, the next best thing is the wrong thing, and the worst thing you can do is nothing.', 'Theodore Roosevelt', 'Motivation', '["decision", "decisiveness", "action"]', 'sunset', 0, 88),
('quote-689', 'Energy and persistence conquer all things.', 'Benjamin Franklin', 'Motivation', '["persistence", "energy", "mastery"]', 'light', 0, 115),
('quote-690', 'An investment in knowledge pays the best interest.', 'Benjamin Franklin', 'Motivation', '["knowledge", "learning", "growth"]', 'emerald', 0, 108),
('quote-691', 'By failing to prepare, you are preparing to fail.', 'Benjamin Franklin', 'Motivation', '["preparation", "planning", "foresight"]', 'midnight', 0, 59),
('quote-692', 'Well done is better than well said.', 'Benjamin Franklin', 'Motivation', '["deeds", "execution", "integrity"]', 'nordic', 0, 126),
('quote-693', 'Lost time is never found again.', 'Benjamin Franklin', 'Motivation', '["time", "urgency", "focus"]', 'sunset', 0, 124),
('quote-694', 'Diligence is the mother of good luck.', 'Benjamin Franklin', 'Motivation', '["diligence", "luck", "effort"]', 'light', 0, 84),
('quote-695', 'Without continual growth and progress, such words as improvement, achievement, and success have no meaning.', 'Benjamin Franklin', 'Motivation', '["growth", "progress", "evolution"]', 'emerald', 0, 98),
('quote-696', 'He that can have patience can have what he will.', 'Benjamin Franklin', 'Motivation', '["patience", "desire", "achievement"]', 'midnight', 0, 86),
('quote-697', 'Small strokes fell great oaks.', 'Benjamin Franklin', 'Motivation', '["consistency", "daily-effort", "persistence"]', 'nordic', 0, 66),
('quote-698', 'Tell me and I forget, teach me and I may remember, involve me and I learn.', 'Benjamin Franklin', 'Motivation', '["engagement", "learning", "action"]', 'sunset', 0, 53),
('quote-699', 'Dream big and dare to fail.', 'Norman Vaughan', 'Motivation', '["big-dreams", "daring", "courage"]', 'light', 0, 118),
('quote-700', 'What you get by achieving your goals is not as important as what you become by achieving your goals.', 'Zig Ziglar', 'Motivation', '["transformation", "goals", "character"]', 'emerald', 0, 123)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-701', 'You don''t have to be great to start, but you have to start to be great.', 'Zig Ziglar', 'Motivation', '["starting", "greatness", "humility"]', 'midnight', 0, 35),
('quote-702', 'Your attitude, not your aptitude, will determine your altitude.', 'Zig Ziglar', 'Motivation', '["attitude", "success", "elevation"]', 'nordic', 0, 131),
('quote-703', 'Lack of direction, not lack of time, is the problem. We all have twenty-four hour days.', 'Zig Ziglar', 'Motivation', '["direction", "time", "focus"]', 'sunset', 0, 133),
('quote-704', 'Expect the best. Prepare for the worst. Capitalize on what comes.', 'Zig Ziglar', 'Motivation', '["readiness", "optimism", "adaptability"]', 'light', 0, 48),
('quote-705', 'People often say that motivation doesn''t last. Well, neither does bathing — that''s why we recommend it daily.', 'Zig Ziglar', 'Motivation', '["daily-habit", "motivation", "renewal"]', 'emerald', 0, 134),
('quote-706', 'There is no traffic jam along the extra mile.', 'Roger Staubach', 'Motivation', '["excellence", "extra-mile", "effort"]', 'midnight', 0, 89),
('quote-707', 'The price of greatness is responsibility.', 'Winston Churchill', 'Motivation', '["responsibility", "greatness", "leadership"]', 'nordic', 0, 63),
('quote-708', 'Either you run the day or the day runs you.', 'Jim Rohn', 'Motivation', '["control", "intention", "mastery"]', 'sunset', 0, 57),
('quote-709', 'Don''t wish it were easier, wish you were better.', 'Jim Rohn', 'Motivation', '["growth", "standard", "strength"]', 'light', 0, 137),
('quote-710', 'Discipline is the bridge between goals and accomplishment.', 'Jim Rohn', 'Motivation', '["discipline", "bridge", "execution"]', 'emerald', 0, 124),
('quote-711', 'If you are not willing to risk the unusual, you will have to settle for the ordinary.', 'Jim Rohn', 'Motivation', '["risk", "unusual", "extraordinary"]', 'midnight', 0, 101),
('quote-712', 'Success is nothing more than a few simple disciplines, practiced every day.', 'Jim Rohn', 'Motivation', '["habits", "daily", "disciplines"]', 'nordic', 0, 94),
('quote-713', 'Motivation is what gets you started. Habit is what keeps you going.', 'Jim Ryun', 'Motivation', '["habits", "momentum", "consistency"]', 'sunset', 0, 41),
('quote-714', 'The only person you are destined to become is the person you decide to be.', 'Ralph Waldo Emerson', 'Motivation', '["decision", "destiny", "identity"]', 'light', 0, 106),
('quote-715', 'Start where you are. Use what you have. Do what you can.', 'Arthur Ashe', 'Motivation', '["pragmatism", "starting", "action"]', 'emerald', 0, 66),
('quote-716', 'Success is the sum of small efforts, repeated day in and day out.', 'Robert Collier', 'Motivation', '["small-steps", "repetition", "consistency"]', 'midnight', 0, 50),
('quote-717', 'The secret of success is constancy to purpose.', 'Benjamin Disraeli', 'Motivation', '["purpose", "constancy", "focus"]', 'nordic', 0, 93),
('quote-718', 'Through perseverance many people win success out of what seemed destined to be certain failure.', 'Benjamin Disraeli', 'Motivation', '["perseverance", "triumph", "grit"]', 'sunset', 0, 52),
('quote-719', 'Action may not always bring happiness, but there is no happiness without action.', 'Benjamin Disraeli', 'Motivation', '["action", "happiness", "movement"]', 'light', 0, 137),
('quote-720', 'I am not a product of my circumstances. I am a product of my decisions.', 'Stephen Covey', 'Motivation', '["decisions", "agency", "ownership"]', 'emerald', 0, 94),
('quote-721', 'Begin with the end in mind.', 'Stephen Covey', 'Motivation', '["vision", "purpose", "planning"]', 'midnight', 0, 120),
('quote-722', 'The key is not to prioritize what''s on your schedule, but to schedule your priorities.', 'Stephen Covey', 'Motivation', '["priorities", "time", "focus"]', 'nordic', 0, 102),
('quote-723', 'Seek first to understand, then to be understood.', 'Stephen Covey', 'Motivation', '["understanding", "empathy", "communication"]', 'sunset', 0, 106),
('quote-724', 'Live out of your imagination, not your history.', 'Stephen Covey', 'Motivation', '["imagination", "future", "reinvention"]', 'light', 0, 111),
('quote-725', 'You can have it all. You just can''t have it all at once.', 'Oprah Winfrey', 'Motivation', '["patience", "balance", "perspective"]', 'emerald', 0, 75),
('quote-726', 'Do what you have to do until you can do what you want to do.', 'Oprah Winfrey', 'Motivation', '["work-ethic", "path", "patience"]', 'midnight', 0, 131),
('quote-727', 'The biggest adventure you can take is to live the life of your dreams.', 'Oprah Winfrey', 'Motivation', '["adventure", "dreams", "boldness"]', 'nordic', 0, 91),
('quote-728', 'Step out of the history that is holding you back. Step into the new story you are willing to create.', 'Oprah Winfrey', 'Motivation', '["reinvention", "story", "courage"]', 'sunset', 0, 113),
('quote-729', 'Where there is no struggle, there is no strength.', 'Oprah Winfrey', 'Motivation', '["struggle", "strength", "growth"]', 'light', 0, 139),
('quote-730', 'Don''t watch the clock; do what it does. Keep going.', 'Sam Levenson', 'Motivation', '["momentum", "keep-going", "persistence"]', 'emerald', 0, 127),
('quote-731', 'Everything you want is on the other side of fear.', 'Jack Canfield', 'Motivation', '["courage", "fear", "breakthrough"]', 'midnight', 0, 99),
('quote-732', 'Decide what you want, decide what you are willing to exchange for it, establish your priorities, and go to work.', 'H.L. Hunt', 'Motivation', '["decisiveness", "sacrifice", "execution"]', 'nordic', 0, 89),
('quote-733', 'Success is walking from failure to failure with no loss of enthusiasm.', 'Winston Churchill', 'Motivation', '["enthusiasm", "resilience", "journey"]', 'sunset', 0, 105),
('quote-734', 'Great acts are made up of small deeds.', 'Lao Tzu', 'Motivation', '["small-deeds", "greatness", "patience"]', 'light', 0, 92),
('quote-735', 'Keep your eyes on the goal, not on the obstacles.', 'Anonymous', 'Motivation', '["focus", "goals", "clarity"]', 'emerald', 0, 55),
('quote-736', 'Your only limit is the amount of effort you are willing to invest.', 'Anonymous', 'Motivation', '["effort", "investment", "limitless"]', 'midnight', 0, 130),
('quote-737', 'Build your own dreams, or someone else will hire you to build theirs.', 'Farrah Gray', 'Motivation', '["ownership", "dreams", "ambition"]', 'nordic', 0, 95),
('quote-738', 'Wake up with determination. Go to bed with satisfaction.', 'George Horace Lorimer', 'Motivation', '["determination", "satisfaction", "daily"]', 'sunset', 0, 92),
('quote-739', 'Difficult roads often lead to beautiful destinations.', 'Anonymous', 'Motivation', '["perseverance", "beauty", "destination"]', 'light', 0, 68),
('quote-740', 'Stay dedicated. It''s not going to happen overnight and it won''t be easy, but it will be worth it.', 'Anonymous', 'Motivation', '["dedication", "worth-it", "patience"]', 'emerald', 0, 131),
('quote-741', 'Make today so awesome yesterday gets jealous.', 'Anonymous', 'Motivation', '["energy", "enthusiasm", "today"]', 'midnight', 0, 66),
('quote-742', 'The best project you will ever work on is you.', 'Anonymous', 'Motivation', '["self-growth", "mastery", "investment"]', 'nordic', 0, 116),
('quote-743', 'Innovation distinguishes between a leader and a follower.', 'Steve Jobs', 'Innovation', '["innovation", "leadership", "differentiation"]', 'sunset', 0, 70),
('quote-744', 'Design is not just what it looks like and feels like. Design is how it works.', 'Steve Jobs', 'Innovation', '["design", "function", "craft"]', 'light', 0, 133),
('quote-745', 'The people who are crazy enough to think they can change the world are the ones who do.', 'Steve Jobs', 'Innovation', '["visionary", "change", "audacity"]', 'emerald', 0, 134),
('quote-746', 'I want to put a ding in the universe.', 'Steve Jobs', 'Innovation', '["impact", "legacy", "ambition"]', 'midnight', 0, 101),
('quote-747', 'You can''t connect the dots looking forward; you can only connect them looking backwards.', 'Steve Jobs', 'Innovation', '["dots", "trust", "perspective"]', 'nordic', 0, 97),
('quote-748', 'If you want something new, you have to stop doing something old.', 'Peter Drucker', 'Innovation', '["change", "reinvention", "innovation"]', 'sunset', 0, 115),
('quote-749', 'The best way to predict the future is to create it.', 'Peter Drucker', 'Innovation', '["future", "creation", "agency"]', 'light', 0, 65),
('quote-750', 'What gets measured gets managed.', 'Peter Drucker', 'Innovation', '["metrics", "management", "focus"]', 'emerald', 0, 70),
('quote-751', 'Knowledge has to be improved, challenged, and increased constantly, or it vanishes.', 'Peter Drucker', 'Innovation', '["learning", "knowledge", "continuous"]', 'midnight', 0, 91),
('quote-752', 'Whenever you see a successful business, someone once made a courageous decision.', 'Peter Drucker', 'Innovation', '["courage", "business", "decisions"]', 'nordic', 0, 44),
('quote-753', 'Move fast and break things. Unless you are breaking stuff, you are not moving fast enough.', 'Mark Zuckerberg', 'Innovation', '["speed", "experimentation", "iteration"]', 'sunset', 0, 126),
('quote-754', 'The biggest risk is not taking any risk.', 'Mark Zuckerberg', 'Innovation', '["risk", "innovation", "boldness"]', 'light', 0, 71),
('quote-755', 'Ideas don''t come out fully formed. They only become clear as you work on them.', 'Mark Zuckerberg', 'Innovation', '["ideas", "execution", "clarity"]', 'emerald', 0, 65),
('quote-756', 'When something is important enough, you do it even if the odds are not in your favor.', 'Elon Musk', 'Innovation', '["resilience", "mission", "odds"]', 'midnight', 0, 69),
('quote-757', 'If you get up in the morning and think the future is going to be better, it is a bright day.', 'Elon Musk', 'Innovation', '["optimism", "future", "vision"]', 'nordic', 0, 77),
('quote-758', 'I think it is possible for ordinary people to choose to be extraordinary.', 'Elon Musk', 'Innovation', '["extraordinary", "choice", "potential"]', 'sunset', 0, 75),
('quote-759', 'Failure is an option here. If things are not failing, you are not innovating enough.', 'Elon Musk', 'Innovation', '["failure", "risk", "innovation"]', 'light', 0, 104),
('quote-760', 'Constantly seek criticism. A well-thought-out critique of what you''re doing is as valuable as gold.', 'Elon Musk', 'Innovation', '["feedback", "criticism", "improvement"]', 'emerald', 0, 45),
('quote-761', 'Persistence is very important. You should not give up unless you are forced to give up.', 'Elon Musk', 'Innovation', '["persistence", "resolve", "space"]', 'midnight', 0, 52),
('quote-762', 'It''s okay to have your eggs in one basket as long as you control what happens to that basket.', 'Elon Musk', 'Innovation', '["focus", "control", "conviction"]', 'nordic', 0, 54),
('quote-763', 'First-principles thinking is the best way to innovate: boil things down to their fundamental truths.', 'Elon Musk', 'Innovation', '["first-principles", "physics", "truth"]', 'sunset', 0, 64),
('quote-764', 'If you double the number of experiments you do per year you''re going to double your inventiveness.', 'Jeff Bezos', 'Innovation', '["experimentation", "inventiveness", "scale"]', 'light', 0, 84),
('quote-765', 'A brand for a company is like a reputation for a person. You earn reputation by trying to do hard things well.', 'Jeff Bezos', 'Innovation', '["brand", "reputation", "excellence"]', 'emerald', 0, 123),
('quote-766', 'What''s dangerous is not to evolve.', 'Jeff Bezos', 'Innovation', '["evolution", "adaptability", "growth"]', 'midnight', 0, 54),
('quote-767', 'If you never want to be criticized, for goodness'' sake don''t do anything new.', 'Jeff Bezos', 'Innovation', '["critics", "novelty", "boldness"]', 'nordic', 0, 125),
('quote-768', 'Work hard, have fun, make history.', 'Jeff Bezos', 'Innovation', '["work-ethic", "fun", "history"]', 'sunset', 0, 62),
('quote-769', 'I knew that if I failed I wouldn''t regret that, but I knew the one thing I might regret is not trying.', 'Jeff Bezos', 'Innovation', '["regret-minimization", "courage", "trying"]', 'light', 0, 43),
('quote-770', 'Invention requires a long-term willingness to be misunderstood.', 'Jeff Bezos', 'Innovation', '["misunderstood", "invention", "patience"]', 'emerald', 0, 88),
('quote-771', 'Life''s too short to hang out with people who aren''t resourceful.', 'Jeff Bezos', 'Innovation', '["resourcefulness", "standards", "company"]', 'midnight', 0, 87),
('quote-772', 'We see our customers as invited guests to a party, and we are the hosts.', 'Jeff Bezos', 'Innovation', '["customer-focus", "hospitality", "service"]', 'nordic', 0, 77),
('quote-773', 'The advance of technology is based on making it fit in so that you don''t really even notice it, so it''s part of everyday life.', 'Bill Gates', 'Innovation', '["technology", "seamless", "everyday"]', 'sunset', 0, 104),
('quote-774', 'Software is a great combination between artistry and engineering.', 'Bill Gates', 'Innovation', '["software", "artistry", "engineering"]', 'light', 0, 94),
('quote-775', 'We always overestimate the change that will occur in the next two years and underestimate the change that will occur in the next ten.', 'Bill Gates', 'Innovation', '["change", "timeline", "perspective"]', 'emerald', 0, 88),
('quote-776', 'Your most unhappy customers are your greatest source of learning.', 'Bill Gates', 'Innovation', '["feedback", "customers", "learning"]', 'midnight', 0, 42),
('quote-777', 'Don''t compare yourself with anyone in this world... if you do so, you are insulting yourself.', 'Bill Gates', 'Innovation', '["individuality", "comparison", "self-worth"]', 'nordic', 0, 61),
('quote-778', 'Patience is a key element of success.', 'Bill Gates', 'Innovation', '["patience", "success", "endurance"]', 'sunset', 0, 88),
('quote-779', 'Success is a lousy teacher. It seduces smart people into thinking they can''t lose.', 'Bill Gates', 'Innovation', '["humility", "success", "learning"]', 'light', 0, 84),
('quote-780', 'Any sufficiently advanced technology is indistinguishable from magic.', 'Arthur C. Clarke', 'Innovation', '["technology", "magic", "future"]', 'emerald', 0, 133),
('quote-781', 'The only way of discovering the limits of the possible is to venture a little way past them into the impossible.', 'Arthur C. Clarke', 'Innovation', '["limits", "impossible", "exploration"]', 'midnight', 0, 109),
('quote-782', 'New ideas pass through three periods: 1) It can''t be done; 2) It probably can be done, but it''s not worth doing; 3) I knew it was a good idea all along!', 'Arthur C. Clarke', 'Innovation', '["ideas", "acceptance", "paradigm"]', 'nordic', 0, 124),
('quote-783', 'We are an impossibility in an impossible universe.', 'Ray Bradbury', 'Innovation', '["wonder", "cosmos", "humanity"]', 'sunset', 0, 37),
('quote-784', 'Science fiction is the most important literature in the history of the world, because it''s the history of ideas, the history of our civilization.', 'Ray Bradbury', 'Innovation', '["scifi", "ideas", "literature"]', 'light', 0, 132),
('quote-785', 'Everything is theoretically impossible, until it is done.', 'Robert A. Heinlein', 'Innovation', '["theory", "action", "breakthrough"]', 'emerald', 0, 108),
('quote-786', 'Progress isn''t made by early risers. It''s made by lazy men trying to find easier ways to do something.', 'Robert A. Heinlein', 'Innovation', '["efficiency", "leverage", "humor"]', 'midnight', 0, 83),
('quote-787', 'Don''t let yesterday take up too much of today.', 'Alan Kay', 'Innovation', '["computing", "future", "now"]', 'nordic', 0, 96),
('quote-788', 'The best way to predict the future is to invent it.', 'Alan Kay', 'Innovation', '["invention", "future", "agency"]', 'sunset', 0, 35),
('quote-789', 'Simple things should be simple, complex things should be possible.', 'Alan Kay', 'Innovation', '["simplicity", "software-design", "architecture"]', 'light', 0, 80),
('quote-790', 'Technology is anything that wasn''t around when you were born.', 'Alan Kay', 'Innovation', '["technology", "perspective", "generations"]', 'emerald', 0, 73),
('quote-791', 'Computer science is no more about computers than astronomy is about telescopes.', 'Edsger W. Dijkstra', 'Innovation', '["computer-science", "abstractions", "science"]', 'midnight', 0, 131),
('quote-792', 'Simplicity is prerequisite for reliability.', 'Edsger W. Dijkstra', 'Innovation', '["simplicity", "reliability", "code"]', 'nordic', 0, 84),
('quote-793', 'If debugging is the process of removing software bugs, then programming must be the process of putting them in.', 'Edsger W. Dijkstra', 'Innovation', '["debugging", "programming", "wit"]', 'sunset', 0, 88),
('quote-794', 'The question of whether machines can think is about as relevant as the question of whether submarines can swim.', 'Edsger W. Dijkstra', 'Innovation', '["artificial-intelligence", "thought", "machines"]', 'light', 0, 103),
('quote-795', 'Talk is cheap. Show me the code.', 'Linus Torvalds', 'Innovation', '["code", "action", "execution"]', 'emerald', 0, 130),
('quote-796', 'Most good programmers do programming not because they expect to get paid, but because it is fun to program.', 'Linus Torvalds', 'Innovation', '["passion", "programming", "play"]', 'midnight', 0, 129),
('quote-797', 'Intelligence is the ability to adapt to change.', 'Stephen Hawking', 'Innovation', '["intelligence", "adaptation", "change"]', 'nordic', 0, 104),
('quote-798', 'Look up at the stars and not down at your feet. Try to make sense of what you see, and wonder about what makes the universe exist.', 'Stephen Hawking', 'Innovation', '["curiosity", "stars", "wonder"]', 'sunset', 0, 137),
('quote-799', 'However difficult life may seem, there is always something you can do and succeed at.', 'Stephen Hawking', 'Innovation', '["resilience", "possibility", "action"]', 'light', 0, 112),
('quote-800', 'Quiet people have the loudest minds.', 'Stephen Hawking', 'Innovation', '["quiet", "mind", "intellect"]', 'emerald', 0, 63)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-801', 'Imagination is more important than knowledge. For knowledge is limited, whereas imagination embraces the entire world.', 'Albert Einstein', 'Innovation', '["imagination", "knowledge", "creativity"]', 'midnight', 0, 97),
('quote-802', 'The important thing is not to stop questioning. Curiosity has its own reason for existence.', 'Albert Einstein', 'Innovation', '["curiosity", "questioning", "wonder"]', 'nordic', 0, 63),
('quote-803', 'Logic will get you from A to Z; imagination will get you everywhere.', 'Albert Einstein', 'Innovation', '["logic", "imagination", "creativity"]', 'sunset', 0, 69),
('quote-804', 'A person who never made a mistake never tried anything new.', 'Albert Einstein', 'Innovation', '["mistakes", "experimentation", "growth"]', 'light', 0, 90),
('quote-805', 'We cannot solve our problems with the same thinking we used when we created them.', 'Albert Einstein', 'Innovation', '["breakthrough", "paradigm", "solutions"]', 'emerald', 0, 97),
('quote-806', 'Look deep into nature, and then you will understand everything better.', 'Albert Einstein', 'Innovation', '["nature", "understanding", "depth"]', 'midnight', 0, 38),
('quote-807', 'Everything should be made as simple as possible, but not simpler.', 'Albert Einstein', 'Innovation', '["simplicity", "elegance", "precision"]', 'nordic', 0, 84),
('quote-808', 'Genius is making complex ideas simple, not making simple ideas complex.', 'Albert Einstein', 'Innovation', '["genius", "clarity", "simplicity"]', 'sunset', 0, 78),
('quote-809', 'Creativity is intelligence having fun.', 'Albert Einstein', 'Innovation', '["creativity", "intelligence", "fun"]', 'light', 0, 120),
('quote-810', 'Peace cannot be kept by force; it can only be achieved by understanding.', 'Albert Einstein', 'Innovation', '["peace", "understanding", "harmony"]', 'emerald', 0, 121),
('quote-811', 'The measure of intelligence is the ability to change.', 'Albert Einstein', 'Innovation', '["intelligence", "change", "adaptation"]', 'midnight', 0, 137),
('quote-812', 'I have no special talents. I am only passionately curious.', 'Albert Einstein', 'Innovation', '["curiosity", "humility", "passion"]', 'nordic', 0, 86),
('quote-813', 'Science without religion is lame, religion without science is blind.', 'Albert Einstein', 'Innovation', '["science", "harmony", "balance"]', 'sunset', 0, 127),
('quote-814', 'The true sign of intelligence is not knowledge but imagination.', 'Albert Einstein', 'Innovation', '["intelligence", "imagination", "vision"]', 'light', 0, 56),
('quote-815', 'Stay curious, for curiosity leads to discovery.', 'Carl Sagan', 'Innovation', '["curiosity", "discovery", "cosmos"]', 'emerald', 0, 94),
('quote-816', 'Somewhere, something incredible is waiting to be known.', 'Carl Sagan', 'Innovation', '["wonder", "discovery", "cosmos"]', 'midnight', 0, 51),
('quote-817', 'We are a way for the cosmos to know itself.', 'Carl Sagan', 'Innovation', '["cosmos", "consciousness", "humanity"]', 'nordic', 0, 114),
('quote-818', 'The cosmos is within us. We are made of star-stuff.', 'Carl Sagan', 'Innovation', '["stars", "connection", "cosmos"]', 'sunset', 0, 103),
('quote-819', 'Extraordinary claims require extraordinary evidence.', 'Carl Sagan', 'Innovation', '["evidence", "truth", "skepticism"]', 'light', 0, 38),
('quote-820', 'For small creatures such as we the vastness is bearable only through love.', 'Carl Sagan', 'Innovation', '["love", "vastness", "connection"]', 'emerald', 0, 85),
('quote-821', 'Science is a way of thinking much more than it is a body of knowledge.', 'Carl Sagan', 'Innovation', '["science", "mindset", "critical-thinking"]', 'midnight', 0, 110),
('quote-822', 'If you wish to make an apple pie from scratch, you must first invent the universe.', 'Carl Sagan', 'Innovation', '["interconnected", "origins", "cosmos"]', 'nordic', 0, 107),
('quote-823', 'Not explaining science seems to me perverse. When you''re in love, you want to tell the world.', 'Carl Sagan', 'Innovation', '["passion", "science", "sharing"]', 'sunset', 0, 119),
('quote-824', 'Science is not only compatible with spirituality; it is a profound source of spirituality.', 'Carl Sagan', 'Innovation', '["spirituality", "science", "awe"]', 'light', 0, 38),
('quote-825', 'The nitrogen in our DNA, the calcium in our teeth, the iron in our blood were made in the interiors of collapsing stars.', 'Carl Sagan', 'Innovation', '["origins", "stars", "unity"]', 'emerald', 0, 45),
('quote-826', 'Curiosity is the engine of achievement.', 'Ken Robinson', 'Innovation', '["curiosity", "achievement", "education"]', 'midnight', 0, 117),
('quote-827', 'If you''re not prepared to be wrong, you''ll never come up with anything original.', 'Ken Robinson', 'Innovation', '["creativity", "mistakes", "originality"]', 'nordic', 0, 89),
('quote-828', 'Human resources are like natural resources; they''re often buried deep.', 'Ken Robinson', 'Innovation', '["potential", "talent", "nurture"]', 'sunset', 0, 52),
('quote-829', 'Role models are only of limited use. For no matter how great you may think someone is, you have to be yourself.', 'Ken Robinson', 'Innovation', '["authenticity", "identity", "individuality"]', 'light', 0, 94),
('quote-830', 'The greatest threat to our planet is the belief that someone else will save it.', 'Robert Swan', 'Innovation', '["responsibility", "environment", "action"]', 'emerald', 0, 58),
('quote-831', 'We cannot direct the wind, but we can adjust our sails.', 'Bertha Calloway', 'Innovation', '["navigation", "resilience", "adaptability"]', 'midnight', 0, 41),
('quote-832', 'A goal without a plan is just a wish.', 'Antoine de Saint-Exupéry', 'Innovation', '["goals", "planning", "execution"]', 'nordic', 0, 68),
('quote-833', 'Perfection is achieved, not when there is nothing more to add, but when there is nothing left to take away.', 'Antoine de Saint-Exupéry', 'Innovation', '["minimalism", "perfection", "design"]', 'sunset', 0, 83),
('quote-834', 'If you want to build a ship, don''t drum up the men to gather wood, divide the work, and give orders. Instead, teach them to yearn for the vast and endless sea.', 'Antoine de Saint-Exupéry', 'Innovation', '["leadership", "vision", "inspiration"]', 'light', 0, 76),
('quote-835', 'What makes the desert beautiful is that somewhere it hides a well.', 'Antoine de Saint-Exupéry', 'Innovation', '["hidden-beauty", "depth", "hope"]', 'emerald', 0, 62),
('quote-836', 'It is only with the heart that one can see rightly; what is essential is invisible to the eye.', 'Antoine de Saint-Exupéry', 'Innovation', '["heart", "essential", "vision"]', 'midnight', 0, 93),
('quote-837', 'The machine does not isolate man from the great problems of nature, but plunges him more deeply into them.', 'Antoine de Saint-Exupéry', 'Innovation', '["technology", "nature", "humanity"]', 'nordic', 0, 76),
('quote-838', 'True innovation occurs when humanity and technology intersect.', 'Anonymous', 'Innovation', '["intersection", "humanity", "tech"]', 'sunset', 0, 78),
('quote-839', 'Code is like humor. When you have to explain it, it’s bad.', 'Cory House', 'Innovation', '["clean-code", "simplicity", "humor"]', 'light', 0, 132),
('quote-840', 'First, solve the problem. Then, write the code.', 'John Johnson', 'Innovation', '["problem-solving", "architecture", "coding"]', 'emerald', 0, 83),
('quote-841', 'Experience is the name everyone gives to their mistakes.', 'Oscar Wilde', 'Innovation', '["experience", "mistakes", "learning"]', 'midnight', 0, 70),
('quote-842', 'The web as I envisaged it, we have not seen it yet. The future is still so much bigger than the past.', 'Tim Berners-Lee', 'Innovation', '["web", "future", "openness"]', 'nordic', 0, 131),
('quote-843', 'Data is a precious thing and will last longer than the systems themselves.', 'Tim Berners-Lee', 'Innovation', '["data", "longevity", "systems"]', 'sunset', 0, 88),
('quote-844', 'We need diversity of thought in the world to face the new challenges.', 'Tim Berners-Lee', 'Innovation', '["diversity", "thought", "challenges"]', 'light', 0, 67),
('quote-845', 'You can''t have great software without a great team.', 'Joel Spolsky', 'Innovation', '["teamwork", "software", "culture"]', 'emerald', 0, 45),
('quote-846', 'Great design is eliminated friction.', 'Anonymous', 'Innovation', '["design", "friction", "elegance"]', 'midnight', 0, 95),
('quote-847', 'The future is already here — it''s just not very evenly distributed.', 'William Gibson', 'Innovation', '["future", "technology", "distribution"]', 'nordic', 0, 37),
('quote-848', 'Cyberspace. A consensual hallucination experienced daily by billions of legitimate operators.', 'William Gibson', 'Innovation', '["cyberspace", "internet", "vision"]', 'sunset', 0, 130),
('quote-849', 'The most profound technologies are those that disappear.', 'Mark Weiser', 'Innovation', '["ubiquitous", "seamless", "tech"]', 'light', 0, 104),
('quote-850', 'Technology is best when it brings people together.', 'Matt Mullenweg', 'Innovation', '["community", "connection", "technology"]', 'emerald', 0, 41),
('quote-851', 'Every great developer you know got there by solving problems they were unqualified to solve until they actually did it.', 'Patrick McKenzie', 'Innovation', '["growth", "learning", "courage"]', 'midnight', 0, 79),
('quote-852', 'Art washes away from the soul the dust of everyday life.', 'Pablo Picasso', 'Poetry & Art', '["art", "soul", "renewal"]', 'nordic', 0, 63),
('quote-853', 'Every child is an artist. The problem is how to remain an artist once he grows up.', 'Pablo Picasso', 'Poetry & Art', '["childhood", "creativity", "art"]', 'sunset', 0, 118),
('quote-854', 'Colors, like features, follow the changes of the emotions.', 'Pablo Picasso', 'Poetry & Art', '["color", "emotion", "expression"]', 'light', 0, 43),
('quote-855', 'Painting is just another way of keeping a diary.', 'Pablo Picasso', 'Poetry & Art', '["painting", "diary", "intimacy"]', 'emerald', 0, 134),
('quote-856', 'Learn the rules like a pro, so you can break them like an artist.', 'Pablo Picasso', 'Poetry & Art', '["rules", "mastery", "rebellion"]', 'midnight', 0, 118),
('quote-857', 'I dream my painting and I paint my dream.', 'Vincent van Gogh', 'Poetry & Art', '["dreams", "painting", "vision"]', 'nordic', 0, 40),
('quote-858', 'If you hear a voice within you say ''you cannot paint,'' then by all means paint, and that voice will be silenced.', 'Vincent van Gogh', 'Poetry & Art', '["courage", "inner-critic", "art"]', 'sunset', 0, 131),
('quote-859', 'Great things are done by a series of small things brought together.', 'Vincent van Gogh', 'Poetry & Art', '["small-steps", "masterpiece", "patience"]', 'light', 0, 38),
('quote-860', 'There is nothing more truly artistic than to love people.', 'Vincent van Gogh', 'Poetry & Art', '["love", "art", "compassion"]', 'emerald', 0, 66),
('quote-861', 'I would rather die of passion than of boredom.', 'Vincent van Gogh', 'Poetry & Art', '["passion", "aliveness", "fire"]', 'midnight', 0, 60),
('quote-862', 'I am seeking, I am striving, I am in it with all my heart.', 'Vincent van Gogh', 'Poetry & Art', '["devotion", "seeking", "striving"]', 'nordic', 0, 37),
('quote-863', 'The heart of man is very much like the sea, it has its storms, it has its tides and in its depths it has its pearls too.', 'Vincent van Gogh', 'Poetry & Art', '["depth", "sea", "pearls"]', 'sunset', 0, 114),
('quote-864', 'The sadness will last forever.', 'Vincent van Gogh', 'Poetry & Art', '["sorrow", "honesty", "vulnerability"]', 'light', 0, 54),
('quote-865', 'Close your eyes and see.', 'James Joyce', 'Poetry & Art', '["imagination", "inner-sight", "vision"]', 'emerald', 0, 65),
('quote-866', 'Poetry is the rhythmical creation of beauty in words.', 'Edgar Allan Poe', 'Poetry & Art', '["beauty", "poetry", "rhythm"]', 'midnight', 0, 51),
('quote-867', 'Those who dream by day are cognizant of many things which escape those who dream only by night.', 'Edgar Allan Poe', 'Poetry & Art', '["daydream", "cognizance", "imagination"]', 'nordic', 0, 95),
('quote-868', 'All that we see or seem is but a dream within a dream.', 'Edgar Allan Poe', 'Poetry & Art', '["dream", "illusion", "mystery"]', 'sunset', 0, 120),
('quote-869', 'Words have no power to impress the mind without the exquisite horror of their reality.', 'Edgar Allan Poe', 'Poetry & Art', '["words", "reality", "literature"]', 'light', 0, 49),
('quote-870', 'To see a World in a Grain of Sand And a Heaven in a Wild Flower, Hold Infinity in the palm of your hand And Eternity in an hour.', 'William Blake', 'Poetry & Art', '["infinity", "eternity", "mysticism"]', 'emerald', 0, 107),
('quote-871', 'The true method of knowledge is experiment.', 'William Blake', 'Poetry & Art', '["knowledge", "experiment", "truth"]', 'midnight', 0, 62),
('quote-872', 'No bird soars too high, if he soars with his own wings.', 'William Blake', 'Poetry & Art', '["independence", "flight", "wings"]', 'nordic', 0, 94),
('quote-873', 'What is now proved was once only imagined.', 'William Blake', 'Poetry & Art', '["imagination", "proof", "creation"]', 'sunset', 0, 124),
('quote-874', 'The tree which moves some to tears of joy is in the eyes of others only a green thing which stands in the way.', 'William Blake', 'Poetry & Art', '["perception", "awe", "nature"]', 'light', 0, 67),
('quote-875', 'He who binds to himself a joy Does the winged life destroy; But he who kisses the joy as it flies Lives in eternity''s sun rise.', 'William Blake', 'Poetry & Art', '["detachment", "joy", "eternity"]', 'emerald', 0, 133),
('quote-876', 'A thing of beauty is a joy forever: Its loveliness increases; it will never pass into nothingness.', 'John Keats', 'Poetry & Art', '["beauty", "joy", "immortality"]', 'midnight', 0, 82),
('quote-877', 'Beauty is truth, truth beauty,—that is all Ye know on earth, and all ye need to know.', 'John Keats', 'Poetry & Art', '["truth", "beauty", "poetic"]', 'nordic', 0, 56),
('quote-878', 'I am certain of nothing but of the holiness of the Heart''s affections and the truth of Imagination.', 'John Keats', 'Poetry & Art', '["heart", "imagination", "holiness"]', 'sunset', 0, 112),
('quote-879', 'Poetry should please by a fine excess and not by singularity.', 'John Keats', 'Poetry & Art', '["excess", "pleasure", "craft"]', 'light', 0, 112),
('quote-880', 'I almost wish we were butterflies and liv''d but three summer days — three such days with you I could fill with more delight than fifty common years could ever contain.', 'John Keats', 'Poetry & Art', '["butterflies", "summer", "delight"]', 'emerald', 0, 130),
('quote-881', 'Hope is the thing with feathers that perches in the soul - and sings the tunes without the words - and never stops at all.', 'Emily Dickinson', 'Poetry & Art', '["hope", "soul", "feathers"]', 'midnight', 0, 126),
('quote-882', 'Forever is composed of nows.', 'Emily Dickinson', 'Poetry & Art', '["now", "forever", "presence"]', 'nordic', 0, 49),
('quote-883', 'Tell all the truth but tell it slant — Success in Circuit lies.', 'Emily Dickinson', 'Poetry & Art', '["truth", "slant", "art"]', 'sunset', 0, 134),
('quote-884', 'I dwell in Possibility — A fairer House than Prose.', 'Emily Dickinson', 'Poetry & Art', '["possibility", "poetry", "architecture"]', 'light', 0, 139),
('quote-885', 'Unable are the loved to die, for love is immortality.', 'Emily Dickinson', 'Poetry & Art', '["immortality", "love", "eternity"]', 'emerald', 0, 55),
('quote-886', 'If I read a book and it makes my whole body so cold no fire can warm me, I know that is poetry.', 'Emily Dickinson', 'Poetry & Art', '["chills", "power", "poetry"]', 'midnight', 0, 74),
('quote-887', 'That it will never come again is what makes life so sweet.', 'Emily Dickinson', 'Poetry & Art', '["sweetness", "impermanence", "presence"]', 'nordic', 0, 48),
('quote-888', 'Nature is what we know — Yet have no art to say — So impotent Our Wisdom is To her Simplicity.', 'Emily Dickinson', 'Poetry & Art', '["nature", "simplicity", "awe"]', 'sunset', 0, 109),
('quote-889', 'Find ecstasy in life; the mere sense of living is joy enough.', 'Emily Dickinson', 'Poetry & Art', '["ecstasy", "living", "joy"]', 'light', 0, 38),
('quote-890', 'Two roads diverged in a wood, and I — I took the one less traveled by, And that has made all the difference.', 'Robert Frost', 'Poetry & Art', '["choices", "individuality", "path"]', 'emerald', 0, 74),
('quote-891', 'The woods are lovely, dark and deep, But I have promises to keep, And miles to go before I sleep.', 'Robert Frost', 'Poetry & Art', '["duty", "woods", "journey"]', 'midnight', 0, 108),
('quote-892', 'Poetry is when an emotion has found its thought and the thought has found words.', 'Robert Frost', 'Poetry & Art', '["emotion", "thought", "craft"]', 'nordic', 0, 121),
('quote-893', 'Happiness makes up in height for what it lacks in length.', 'Robert Frost', 'Poetry & Art', '["height", "happiness", "intensity"]', 'sunset', 0, 83),
('quote-894', 'Like a piece of ice on a hot stove the poem must ride on its own melting.', 'Robert Frost', 'Poetry & Art', '["poem", "metaphor", "organic"]', 'light', 0, 85),
('quote-895', 'Freedom lies in being bold.', 'Robert Frost', 'Poetry & Art', '["freedom", "boldness", "courage"]', 'emerald', 0, 126),
('quote-896', 'No tears in the writer, no tears in the reader. No surprise in the writer, no surprise in the reader.', 'Robert Frost', 'Poetry & Art', '["honesty", "surprise", "emotion"]', 'midnight', 0, 60),
('quote-897', 'Love is the irresistible desire to be irresistibly desired.', 'Robert Frost', 'Poetry & Art', '["desire", "reciprocity", "love"]', 'nordic', 0, 44),
('quote-898', 'Do not go gentle into that good night, Old age should burn and rave at close of day; Rage, rage against the dying of the light.', 'Dylan Thomas', 'Poetry & Art', '["defiance", "light", "fire"]', 'sunset', 0, 110),
('quote-899', 'Though lovers be lost, love shall not; And death shall have no dominion.', 'Dylan Thomas', 'Poetry & Art', '["triumph", "eternal", "love"]', 'light', 0, 123),
('quote-900', 'The ball I threw while playing in the park has not yet reached the ground.', 'Dylan Thomas', 'Poetry & Art', '["nostalgia", "time", "suspension"]', 'emerald', 0, 115)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-901', 'Art is not what you see, but what you make others see.', 'Edgar Degas', 'Poetry & Art', '["vision", "art", "perspective"]', 'midnight', 0, 66),
('quote-902', 'Creativity takes courage.', 'Henri Matisse', 'Poetry & Art', '["creativity", "courage", "boldness"]', 'nordic', 0, 48),
('quote-903', 'There are always flowers for those who want to see them.', 'Henri Matisse', 'Poetry & Art', '["flowers", "optimism", "beauty"]', 'sunset', 0, 124),
('quote-904', 'An artist must never be a prisoner. Prisoner? An artist should never be a prisoner of himself, prisoner of style, prisoner of a reputation, prisoner of success.', 'Henri Matisse', 'Poetry & Art', '["freedom", "artist", "growth"]', 'light', 0, 133),
('quote-905', 'Color is the keyboard, the eyes are the hammers, the soul is the piano with many strings.', 'Wassily Kandinsky', 'Poetry & Art', '["synesthesia", "color", "soul"]', 'emerald', 0, 73),
('quote-906', 'Everything starts from a dot.', 'Wassily Kandinsky', 'Poetry & Art', '["dot", "origins", "canvas"]', 'midnight', 0, 122),
('quote-907', 'The artist must train not only his eye but also his soul.', 'Wassily Kandinsky', 'Poetry & Art', '["soul", "discipline", "art"]', 'nordic', 0, 111),
('quote-908', 'Art is a lie that makes us realize truth.', 'Pablo Picasso', 'Poetry & Art', '["paradox", "truth", "illusion"]', 'sunset', 0, 138),
('quote-909', 'To create one''s own world in any of the arts takes courage.', 'Georgia O''Keeffe', 'Poetry & Art', '["world-building", "courage", "canvas"]', 'light', 0, 50),
('quote-910', 'I found I could say things with color and shapes that I couldn''t say any other way — things I had no words for.', 'Georgia O''Keeffe', 'Poetry & Art', '["color", "unspoken", "shapes"]', 'emerald', 0, 136),
('quote-911', 'Whether you succeed or not is irrelevant, there is no such thing. Making your unknown known is the important thing.', 'Georgia O''Keeffe', 'Poetry & Art', '["expression", "unknown", "authenticity"]', 'midnight', 0, 107),
('quote-912', 'I have already settled it for myself so flattery and criticism go down the same drain and I am quite free.', 'Georgia O''Keeffe', 'Poetry & Art', '["freedom", "criticism", "peace"]', 'nordic', 0, 135),
('quote-913', 'Every artist was first an amateur.', 'Ralph Waldo Emerson', 'Poetry & Art', '["amateur", "beginnings", "humility"]', 'sunset', 0, 40),
('quote-914', 'Painting is poetry that is seen rather than felt, and poetry is painting that is felt rather than seen.', 'Leonardo da Vinci', 'Poetry & Art', '["painting", "poetry", "senses"]', 'light', 0, 79),
('quote-915', 'The artist sees what others only catch a glimpse of.', 'Leonardo da Vinci', 'Poetry & Art', '["gaze", "depth", "perception"]', 'emerald', 0, 103),
('quote-916', 'Art enables us to find ourselves and lose ourselves at the same time.', 'Thomas Merton', 'Poetry & Art', '["paradox", "identity", "art"]', 'midnight', 0, 89),
('quote-917', 'The aim of art is to represent not the outward appearance of things, but their inward significance.', 'Aristotle', 'Poetry & Art', '["significance", "inward", "essence"]', 'nordic', 0, 119),
('quote-918', 'We have art in order not to die of the truth.', 'Friedrich Nietzsche', 'Poetry & Art', '["truth", "shelter", "beauty"]', 'sunset', 0, 82),
('quote-919', 'Poetry is the spontaneous overflow of powerful feelings: it takes its origin from emotion recollected in tranquility.', 'William Wordsworth', 'Poetry & Art', '["emotion", "tranquility", "spontaneous"]', 'light', 0, 43),
('quote-920', 'The earth has music for those who listen.', 'William Shakespeare', 'Poetry & Art', '["earth", "music", "listening"]', 'emerald', 0, 99),
('quote-921', 'All the world''s a stage, and all the men and women merely players.', 'William Shakespeare', 'Poetry & Art', '["stage", "theatre", "humanity"]', 'midnight', 0, 117),
('quote-922', 'Music can change the world because it can change people.', 'Bono', 'Poetry & Art', '["music", "change", "humanity"]', 'nordic', 0, 78),
('quote-923', 'The artist''s job is not to succumb to despair, but to find an antidote to the emptiness of existence.', 'Gertrude Stein', 'Poetry & Art', '["antidote", "purpose", "hope"]', 'sunset', 0, 36),
('quote-924', 'Poetry is an echo, asking a shadow to dance.', 'Carl Sandburg', 'Poetry & Art', '["echo", "dance", "shadow"]', 'light', 0, 88),
('quote-925', 'Fog comes on little cat feet.', 'Carl Sandburg', 'Poetry & Art', '["imagery", "nature", "gentle"]', 'emerald', 0, 140),
('quote-926', 'Nothing is softer or more flexible than water, yet nothing can resist it.', 'Lao Tzu', 'Poetry & Art', '["water", "yielding", "strength"]', 'midnight', 0, 97),
('quote-927', 'To paint is to love again.', 'Henry Miller', 'Poetry & Art', '["painting", "rebirth", "love"]', 'nordic', 0, 48),
('quote-928', 'Develop an interest in life as you see it; the people, things, literature, music — the world is so rich.', 'Henry Miller', 'Poetry & Art', '["curiosity", "richness", "engagement"]', 'sunset', 0, 90),
('quote-929', 'Art is the signature of civilizations.', 'Beverly Sills', 'Poetry & Art', '["civilization", "legacy", "culture"]', 'light', 0, 81),
('quote-930', 'A room without books is like a body without a soul.', 'Cicero', 'Poetry & Art', '["books", "soul", "sanctuary"]', 'emerald', 0, 116),
('quote-931', 'There is no friend as loyal as a book.', 'Ernest Hemingway', 'Poetry & Art', '["books", "friendship", "loyalty"]', 'midnight', 0, 93),
('quote-932', 'Write hard and clear about what hurts.', 'Ernest Hemingway', 'Poetry & Art', '["vulnerability", "clarity", "honesty"]', 'nordic', 0, 125),
('quote-933', 'In order to write about life first you must live it.', 'Ernest Hemingway', 'Poetry & Art', '["experience", "living", "writing"]', 'sunset', 0, 54),
('quote-934', 'The world breaks everyone and afterward many are strong at the broken places.', 'Ernest Hemingway', 'Poetry & Art', '["kintsugi", "strength", "broken"]', 'light', 0, 90),
('quote-935', 'There is nothing to writing. All you do is sit down at a typewriter and bleed.', 'Ernest Hemingway', 'Poetry & Art', '["craft", "raw", "dedication"]', 'emerald', 0, 57),
('quote-936', 'You must write the book that wants to be written.', 'Madeleine L''Engle', 'Poetry & Art', '["authenticity", "calling", "creation"]', 'midnight', 0, 128),
('quote-937', 'Literature is the most agreeable way of ignoring life.', 'Fernando Pessoa', 'Poetry & Art', '["literature", "imagination", "refuge"]', 'nordic', 0, 101),
('quote-938', 'My soul is a hidden orchestra; I know not what instruments, what fiddlestrings and harps, drums and tambours, sound and clash inside me.', 'Fernando Pessoa', 'Poetry & Art', '["orchestra", "inner-depth", "music"]', 'sunset', 0, 118),
('quote-939', 'To be great, be whole; exclude nothing, exaggerate nothing that is not you.', 'Fernando Pessoa', 'Poetry & Art', '["wholeness", "authenticity", "greatness"]', 'light', 0, 69),
('quote-940', 'Art is contemplation; it is the pleasure of the mind which searches into nature and which there divines the spirit.', 'Auguste Rodin', 'Poetry & Art', '["contemplation", "nature", "spirit"]', 'emerald', 0, 113),
('quote-941', 'Patience is also a form of action.', 'Auguste Rodin', 'Poetry & Art', '["patience", "action", "sculpture"]', 'midnight', 0, 138),
('quote-942', 'Nothing is a waste of time if you use the experience wisely.', 'Auguste Rodin', 'Poetry & Art', '["experience", "learning", "wisdom"]', 'nordic', 0, 103),
('quote-943', 'Art is the stored honey of the human soul.', 'Theodore Dreiser', 'Poetry & Art', '["honey", "soul", "nectar"]', 'sunset', 0, 134),
('quote-944', 'The purpose of art is washing the dust of daily life off our souls.', 'Pablo Picasso', 'Poetry & Art', '["cleansing", "renewal", "soul"]', 'light', 0, 96),
('quote-945', 'Every great artist writes his own autobiography in his work.', 'Ellis Yarnal', 'Poetry & Art', '["autobiography", "canvas", "expression"]', 'emerald', 0, 94),
('quote-946', 'Painting is silent poetry, and poetry is painting that speaks.', 'Plutarch', 'Poetry & Art', '["painting", "speech", "harmony"]', 'midnight', 0, 90),
('quote-947', 'True art is characterized by an irresistible urge in the creative artist.', 'Albert Einstein', 'Poetry & Art', '["urge", "creativity", "calling"]', 'nordic', 0, 140),
('quote-948', 'The soul that sees beauty may sometimes walk alone.', 'Johann Wolfgang von Goethe', 'Poetry & Art', '["beauty", "solitude", "wonder"]', 'sunset', 0, 128),
('quote-949', 'Architecture is frozen music.', 'Johann Wolfgang von Goethe', 'Poetry & Art', '["architecture", "music", "harmony"]', 'light', 0, 110),
('quote-950', 'Daring ideas are like chessmen moved forward; they may be beaten, but they may start a winning game.', 'Johann Wolfgang von Goethe', 'Poetry & Art', '["daring", "chess", "ideas"]', 'emerald', 0, 69),
('quote-951', 'Whatever you can do, or dream you can, begin it. Boldness has genius, power, and magic in it.', 'Johann Wolfgang von Goethe', 'Poetry & Art', '["boldness", "magic", "begin"]', 'midnight', 0, 76),
('quote-952', 'Art is a step from what is the obvious and well-known toward what is arcane and concealed.', 'Kahlil Gibran', 'Poetry & Art', '["mystery", "arcane", "depth"]', 'nordic', 0, 66),
('quote-953', 'Beauty is eternity gazing at itself in a mirror. But you are eternity and you are the mirror.', 'Kahlil Gibran', 'Poetry & Art', '["eternity", "mirror", "beauty"]', 'sunset', 0, 46),
('quote-954', 'Music is the language of the spirit. It opens the secret of life bringing peace, abolishing strife.', 'Kahlil Gibran', 'Poetry & Art', '["music", "spirit", "peace"]', 'light', 0, 70),
('quote-955', 'The poet is a bird of unearthly plumage in whose heart are gathered all the world''s sorrows and joys.', 'Kahlil Gibran', 'Poetry & Art', '["poet", "sorrow", "joy"]', 'emerald', 0, 92),
('quote-956', 'Art is the unceasing effort to compete with the beauty of flowers — and never succeeding.', 'Marc Chagall', 'Poetry & Art', '["flowers", "humility", "nature"]', 'midnight', 0, 66),
('quote-957', 'In our life there is a single color, as on an artist''s palette, which provides the meaning of life and art. It is the color of love.', 'Marc Chagall', 'Poetry & Art', '["love", "palette", "meaning"]', 'nordic', 0, 131),
('quote-958', 'If I create from the heart, nearly everything works; if from the head, almost nothing.', 'Marc Chagall', 'Poetry & Art', '["heart", "intuition", "creation"]', 'sunset', 0, 94),
('quote-959', 'Only work which is the product of inner necessity can be called true art.', 'Wassily Kandinsky', 'Poetry & Art', '["necessity", "authenticity", "true-art"]', 'light', 0, 107),
('quote-960', 'The creation of something new is not accomplished by the intellect but by the play instinct.', 'Carl Jung', 'Poetry & Art', '["play", "creation", "unconscious"]', 'emerald', 0, 113),
('quote-961', 'Art is a harmony parallel with nature.', 'Paul Cézanne', 'Poetry & Art', '["harmony", "nature", "canvas"]', 'midnight', 0, 120),
('quote-962', 'A work of art which did not begin in emotion is not art.', 'Paul Cézanne', 'Poetry & Art', '["emotion", "origins", "craft"]', 'nordic', 0, 83),
('quote-963', 'Courage is not the absence of fear, but the triumph over it.', 'Nelson Mandela', 'Courage', '["triumph", "fearlessness", "courage"]', 'sunset', 0, 78),
('quote-964', 'The brave man is not he who does not feel afraid, but he who conquers that fear.', 'Nelson Mandela', 'Courage', '["conquering", "bravery", "strength"]', 'light', 0, 38),
('quote-965', 'I learned that courage was not the absence of fear, but the triumph over it.', 'Nelson Mandela', 'Courage', '["fear", "triumph", "resilience"]', 'emerald', 0, 98),
('quote-966', 'It takes courage to grow up and become who you really are.', 'E.E. Cummings', 'Courage', '["authenticity", "growth", "identity"]', 'midnight', 0, 76),
('quote-967', 'Courage starts with showing up and letting ourselves be seen.', 'Brené Brown', 'Courage', '["vulnerability", "presence", "courage"]', 'nordic', 0, 58),
('quote-968', 'Vulnerability is not winning or losing; it''s having the courage to show up when you can''t control the outcome.', 'Brené Brown', 'Courage', '["vulnerability", "daring", "grit"]', 'sunset', 0, 97),
('quote-969', 'You can choose courage or you can choose comfort, but you cannot choose both.', 'Brené Brown', 'Courage', '["choices", "growth", "comfort-zone"]', 'light', 0, 62),
('quote-970', 'Imperfections are not inadequacies; they are reminders that we''re all in this together.', 'Brené Brown', 'Courage', '["imperfection", "connection", "compassion"]', 'emerald', 0, 80),
('quote-971', 'Courage is being scared to death, but saddling up anyway.', 'John Wayne', 'Courage', '["grit", "action", "fear"]', 'midnight', 0, 137),
('quote-972', 'You have been assigned this mountain to show others it can be moved.', 'Mel Robbins', 'Courage', '["mountain", "inspiration", "strength"]', 'nordic', 0, 68),
('quote-973', 'You are one decision away from a completely different life.', 'Mel Robbins', 'Courage', '["decisions", "breakthrough", "agency"]', 'sunset', 0, 78),
('quote-974', 'Doubt kills more dreams than failure ever will.', 'Suzy Kassem', 'Courage', '["doubt", "dreams", "confidence"]', 'light', 0, 70),
('quote-975', 'Fear is a reaction. Courage is a decision.', 'Winston Churchill', 'Courage', '["decision", "reaction", "fear"]', 'emerald', 0, 111),
('quote-976', 'He who is brave is free.', 'Seneca', 'Courage', '["freedom", "bravery", "liberty"]', 'midnight', 0, 124),
('quote-977', 'Man cannot discover new oceans unless he has the courage to lose sight of the shore.', 'André Gide', 'Courage', '["oceans", "shore", "discovery"]', 'nordic', 0, 70),
('quote-978', 'It is during our darkest moments that we must focus to see the light.', 'Aristotle Onassis', 'Courage', '["darkness", "light", "focus"]', 'sunset', 0, 106),
('quote-979', 'A ship in harbor is safe, but that is not what ships are built for.', 'John A. Shedd', 'Courage', '["harbor", "purpose", "voyage"]', 'light', 0, 36),
('quote-980', 'The only thing we have to fear is fear itself.', 'Franklin D. Roosevelt', 'Courage', '["fear", "courage", "leadership"]', 'emerald', 0, 101),
('quote-981', 'There is a stubbornness about me that never can bear to be frightened at the will of others. My courage always rises at every attempt to intimidate me.', 'Jane Austen', 'Courage', '["defiance", "fortitude", "courage"]', 'midnight', 0, 59),
('quote-982', 'I am not afraid of storms, for I am learning how to sail my ship.', 'Louisa May Alcott', 'Courage', '["storms", "learning", "self-reliance"]', 'nordic', 0, 45),
('quote-983', 'She stood in the storm and when the wind did not blow her way, she adjusted her sails.', 'Elizabeth Edwards', 'Courage', '["sails", "resilience", "grace"]', 'sunset', 0, 65),
('quote-984', 'Life shrinks or expands in proportion to one''s courage.', 'Anaïs Nin', 'Courage', '["expansion", "courage", "living"]', 'light', 0, 127),
('quote-985', 'And the day came when the risk to remain tight in a bud was more painful than the risk it took to blossom.', 'Anaïs Nin', 'Courage', '["blossom", "transformation", "risk"]', 'emerald', 0, 87),
('quote-986', 'We don''t see things as they are, we see them as we are.', 'Anaïs Nin', 'Courage', '["perception", "inward", "lens"]', 'midnight', 0, 97),
('quote-987', 'Have courage for the great sorrows of life and patience for the small ones; and when you have laboriously accomplished your daily task, go to sleep in peace.', 'Victor Hugo', 'Courage', '["peace", "sorrows", "endurance"]', 'nordic', 0, 106),
('quote-988', 'Even the darkest night will end and the sun will rise.', 'Victor Hugo', 'Courage', '["dawn", "sun", "hope"]', 'sunset', 0, 132),
('quote-989', 'Confront the dark parts of yourself, and work to banish them with illumination and forgiveness.', 'August Wilson', 'Courage', '["illumination", "shadow", "forgiveness"]', 'light', 0, 65),
('quote-990', 'Everything you''ve ever wanted is sitting on the other side of fear.', 'George Addair', 'Courage', '["breakthrough", "desire", "overcoming"]', 'emerald', 0, 123),
('quote-991', 'Real courage is when you know you''re licked before you begin, but you begin anyway and see it through no matter what.', 'Harper Lee', 'Courage', '["grit", "conviction", "integrity"]', 'midnight', 0, 95),
('quote-992', 'It''s not whether you get knocked down, it''s whether you get up.', 'Vince Lombardi', 'Courage', '["resilience", "rising", "persistence"]', 'nordic', 0, 117),
('quote-993', 'The measure of who we are is what we do with what we have.', 'Vince Lombardi', 'Courage', '["resourcefulness", "character", "duty"]', 'sunset', 0, 126),
('quote-994', 'Perfection is not attainable, but if we chase perfection we can catch excellence.', 'Vince Lombardi', 'Courage', '["excellence", "striving", "pursuit"]', 'light', 0, 97),
('quote-995', 'The greatest oak was once a little nut that held its ground.', 'Anonymous', 'Courage', '["roots", "holding-ground", "growth"]', 'emerald', 0, 92),
('quote-996', 'Breathe. Let go. And remind yourself that this very moment is the only one you know you have for sure.', 'Oprah Winfrey', 'Courage', '["breath", "moment", "presence"]', 'midnight', 0, 136),
('quote-997', 'You may encounter many defeats, but you must not be defeated.', 'Maya Angelou', 'Courage', '["undefeated", "resilience", "endurance"]', 'nordic', 0, 37),
('quote-998', 'My mission in life is not merely to survive, but to thrive; and to do so with some passion, some compassion, some humor, and some style.', 'Maya Angelou', 'Courage', '["thriving", "passion", "style"]', 'sunset', 0, 46),
('quote-999', 'I can be changed by what happens to me. But I refuse to be reduced by it.', 'Maya Angelou', 'Courage', '["unbroken", "sovereignty", "strength"]', 'light', 0, 72),
('quote-1000', 'We delight in the beauty of the butterfly, but rarely admit the changes it has gone through to achieve that beauty.', 'Maya Angelou', 'Courage', '["metamorphosis", "struggle", "beauty"]', 'emerald', 0, 63)
INSERT INTO `quotes` (`id`, `text`, `author`, `category`, `tags`, `theme`, `is_custom`, `likes`)
VALUES
('quote-1001', 'History, despite its wrenching pain, cannot be unlived, but if faced with courage, need not be lived again.', 'Maya Angelou', 'Courage', '["history", "courage", "healing"]', 'midnight', 0, 86),
('quote-1002', 'Nothing can dim the light which shines from within.', 'Maya Angelou', 'Courage', '["inner-light", "indomitable", "radiance"]', 'nordic', 0, 123),
('quote-1003', 'Courage is the most important of all the virtues because without courage, you can''t practice any other virtue consistently.', 'Maya Angelou', 'Courage', '["virtue", "foundation", "consistency"]', 'sunset', 0, 66),
('quote-1004', 'If you''re always trying to be normal you will never know how amazing you can be.', 'Maya Angelou', 'Courage', '["uniqueness", "authenticity", "amazing"]', 'light', 0, 74),
('quote-1005', 'Try to be a rainbow in someone''s cloud.', 'Maya Angelou', 'Courage', '["kindness", "rainbow", "service"]', 'emerald', 0, 119),
('quote-1006', 'The brave do not live forever, but the cautious do not live at all.', 'Meg Cabot', 'Courage', '["living", "caution", "boldness"]', 'midnight', 0, 109),
('quote-1007', 'Bravery is being the only one who knows you''re afraid.', 'David Hackworth', 'Courage', '["quiet-courage", "stealth", "resolve"]', 'nordic', 0, 82),
('quote-1008', 'It takes a great deal of bravery to stand up to our enemies, but just as much to stand up to our friends.', 'J.K. Rowling', 'Courage', '["integrity", "loyalty", "bravery"]', 'sunset', 0, 95),
('quote-1009', 'We must all face the choice between what is right and what is easy.', 'J.K. Rowling', 'Courage', '["choices", "morality", "conviction"]', 'light', 0, 105),
('quote-1010', 'It matters not what someone is born, but what they grow to be.', 'J.K. Rowling', 'Courage', '["growth", "potential", "becoming"]', 'emerald', 0, 102),
('quote-1011', 'Rock bottom became the solid foundation on which I rebuilt my life.', 'J.K. Rowling', 'Courage', '["rock-bottom", "foundation", "rebuilding"]', 'midnight', 0, 79),
('quote-1012', 'Do not pity the dead. Pity the living, and, above all, those who live without love.', 'J.K. Rowling', 'Courage', '["love", "living", "compassion"]', 'nordic', 0, 89),
('quote-1013', 'What''s coming will come, and we''ll meet it when it does.', 'J.K. Rowling', 'Courage', '["equanimity", "acceptance", "fortitude"]', 'sunset', 0, 130),
('quote-1014', 'It does not do to dwell on dreams and forget to live.', 'J.K. Rowling', 'Courage', '["living", "presence", "action"]', 'light', 0, 105),
('quote-1015', 'Fear of a name increases fear of the thing itself.', 'J.K. Rowling', 'Courage', '["facing-fear", "clarity", "naming"]', 'emerald', 0, 77),
('quote-1016', 'Words are, in my not-so-humble opinion, our most inexhaustible source of magic.', 'J.K. Rowling', 'Courage', '["words", "magic", "power"]', 'midnight', 0, 80),
('quote-1017', 'The strength of the wolf is the pack, and the strength of the pack is the wolf.', 'Rudyard Kipling', 'Courage', '["unity", "teamwork", "strength"]', 'nordic', 0, 124),
('quote-1018', 'If you can keep your head when all about you Are losing theirs and blaming it on you...', 'Rudyard Kipling', 'Courage', '["calm", "stoicism", "mastery"]', 'sunset', 0, 93),
('quote-1019', 'If you can meet with Triumph and Disaster And treat those two impostors just the same...', 'Rudyard Kipling', 'Courage', '["equanimity", "triumph", "disaster"]', 'light', 0, 69),
('quote-1020', 'No pressure, no diamonds.', 'Thomas Carlyle', 'Courage', '["pressure", "diamonds", "transformation"]', 'emerald', 0, 74),
('quote-1021', 'Permanence, perseverance and persistence in spite of all obstacles, discouragements, and impossibilities: It is this, that in all things distinguishes the strong soul from the weak.', 'Thomas Carlyle', 'Courage', '["perseverance", "soul", "distinction"]', 'midnight', 0, 67),
('quote-1022', 'The tragedy of life is what dies inside a man while he lives.', 'Albert Schweitzer', 'Courage', '["vitality", "aliveness", "spirit"]', 'nordic', 0, 64),
('quote-1023', 'At times our own light goes out and is rekindled by a spark from another person.', 'Albert Schweitzer', 'Courage', '["spark", "community", "gratitude"]', 'sunset', 0, 50),
('quote-1024', 'Constant kindness can accomplish much. As the sun makes ice melt, kindness causes misunderstanding, mistrust, and hostility to evaporate.', 'Albert Schweitzer', 'Courage', '["kindness", "gentleness", "warmth"]', 'light', 0, 127),
('quote-1025', 'The purpose of human life is to serve, and to show compassion and the will to help others.', 'Albert Schweitzer', 'Courage', '["service", "compassion", "purpose"]', 'emerald', 0, 59),
('quote-1026', 'Do something wonderful, people may imitate it.', 'Albert Schweitzer', 'Courage', '["inspiration", "example", "action"]', 'midnight', 0, 75),
('quote-1027', 'Success is how high you bounce when you hit bottom.', 'George S. Patton', 'Courage', '["bounce-back", "resilience", "grit"]', 'nordic', 0, 50),
('quote-1028', 'Courage is fear holding on a minute longer.', 'George S. Patton', 'Courage', '["endurance", "fear", "one-minute-more"]', 'sunset', 0, 130),
('quote-1029', 'Accept the challenges so that you can feel the exhilaration of victory.', 'George S. Patton', 'Courage', '["challenge", "victory", "exhilaration"]', 'light', 0, 103),
('quote-1030', 'Better to fight for something than live for nothing.', 'George S. Patton', 'Courage', '["purpose", "conviction", "fight"]', 'emerald', 0, 132),
('quote-1031', 'A good plan violently executed now is better than a perfect plan executed next week.', 'George S. Patton', 'Courage', '["decisiveness", "execution", "speed"]', 'midnight', 0, 123),
('quote-1032', 'I am not what happened to me, I am what I choose to become.', 'Carl Jung', 'Courage', '["identity", "choice", "transformation"]', 'nordic', 0, 58),
('quote-1033', 'Until you make the unconscious conscious, it will direct your life and you will call it fate.', 'Carl Jung', 'Courage', '["consciousness", "awareness", "fate"]', 'sunset', 0, 59),
('quote-1034', 'Your visions will become clear only when you can look into your own heart. Who looks outside, dreams; who looks inside, awakes.', 'Carl Jung', 'Courage', '["heart", "awakening", "introspection"]', 'light', 0, 62),
('quote-1035', 'There is no coming to consciousness without pain.', 'Carl Jung', 'Courage', '["growth", "consciousness", "pain"]', 'emerald', 0, 129),
('quote-1036', 'The privilege of a lifetime is to become who you truly are.', 'Carl Jung', 'Courage', '["individuation", "authenticity", "privilege"]', 'midnight', 0, 96),
('quote-1037', 'Knowing your own darkness is the best method for dealing with the darknesses of other people.', 'Carl Jung', 'Courage', '["shadow", "empathy", "self-knowledge"]', 'nordic', 0, 70),
('quote-1038', 'The meeting of two personalities is like the contact of two chemical substances: if there is any reaction, both are transformed.', 'Carl Jung', 'Courage', '["transformation", "connection", "chemistry"]', 'sunset', 0, 127),
('quote-1039', 'Even a happy life cannot be without a measure of darkness, and the word happy would lose its meaning if it were not balanced by sadness.', 'Carl Jung', 'Courage', '["balance", "darkness", "meaning"]', 'light', 0, 110),
('quote-1040', 'Thinking is difficult, that’s why most people judge.', 'Carl Jung', 'Courage', '["discernment", "judgment", "thinking"]', 'emerald', 0, 132),
('quote-1041', 'You cannot protect yourself from sadness without protecting yourself from happiness.', 'Jonathan Safran Foer', 'Courage', '["vulnerability", "feeling", "wholeness"]', 'midnight', 0, 102),
('quote-1042', 'The human capacity for burden is like bamboo — far more flexible than you''d ever believe at first glance.', 'Jodi Picoult', 'Courage', '["flexibility", "endurance", "bamboo"]', 'nordic', 0, 111),
('quote-1043', 'Sometimes the bravest thing you can do is just to keep breathing.', 'Anonymous', 'Courage', '["survival", "gentle-courage", "breath"]', 'sunset', 0, 71),
('quote-1044', 'Scars remind us that the past was real, but they don''t have to dictate our future.', 'Anonymous', 'Courage', '["scars", "future", "healing"]', 'light', 0, 47),
('quote-1045', 'She was a wild storm that refused to apologize for the thunder she made.', 'Anonymous', 'Courage', '["authenticity", "power", "unapologetic"]', 'emerald', 0, 59),
('quote-1046', 'The strongest people are not those who show strength in front of us but those who win battles we know nothing about.', 'Anonymous', 'Courage', '["hidden-battles", "quiet-strength", "compassion"]', 'midnight', 0, 72),
('quote-1047', 'Fall down seven times, get up eight with fire in your soul.', 'Anonymous', 'Courage', '["fire", "rising", "grit"]', 'nordic', 0, 64),
('quote-1048', 'Your strength is forged in the fires you refused to run from.', 'Anonymous', 'Courage', '["forge", "fires", "endurance"]', 'sunset', 0, 81),
('quote-1049', 'Let your courage be stronger than your fears and your faith larger than your doubts.', 'Anonymous', 'Courage', '["faith", "courage", "doubt"]', 'light', 0, 57),
('quote-1050', 'Even the tallest mountain yields to footsteps taken one by one.', 'Anonymous', 'Courage', '["steps", "patience", "mountain"]', 'emerald', 0, 73),
('quote-1051', 'Within every winter lies an invincible spring waiting for its time.', 'Anonymous', 'Courage', '["spring", "renewal", "winter"]', 'midnight', 0, 36),
('quote-1052', 'Courage does not always roar. Sometimes courage is the quiet voice at the end of the day saying, ''I will try again tomorrow.''', 'Mary Anne Radmacher', 'Courage', '["quiet-voice", "try-again", "tomorrow"]', 'nordic', 0, 125),
('quote-1053', 'Live with intention. Walk to the edge. Listen hard. Practice wellness. Play with abandon. Laugh. Choose with no regret. Continue to learn.', 'Mary Anne Radmacher', 'Courage', '["intention", "edge", "wellness"]', 'sunset', 0, 103),
('quote-1054', 'As we work to create light for others, we naturally light our own way.', 'Mary Anne Radmacher', 'Courage', '["light", "service", "illumination"]', 'light', 0, 51),
('quote-1055', 'No storm can last forever; the clouds will break and the sky will clear.', 'Anonymous', 'Courage', '["clouds", "clearing", "patience"]', 'emerald', 0, 70),
('quote-1056', 'Walk through the fire and emerge as gold.', 'Anonymous', 'Courage', '["alchemy", "gold", "transcendence"]', 'midnight', 0, 40),
('quote-1057', 'Do not pray for an easy life, pray for the strength to endure a difficult one.', 'Bruce Lee', 'Courage', '["strength", "prayer", "endurance"]', 'nordic', 0, 41),
('quote-1058', 'Be like water making its way through cracks. Do not be assertive, but adjust to the object, and you shall find a way around or through it.', 'Bruce Lee', 'Courage', '["water", "adaptability", "flow"]', 'sunset', 0, 105),
('quote-1059', 'Empty your mind, be formless. Shapeless, like water. If you put water into a cup, it becomes the cup.', 'Bruce Lee', 'Courage', '["water", "formless", "zen"]', 'light', 0, 72),
('quote-1060', 'Defeat is a state of mind; no one is ever defeated until defeat has been accepted as a reality.', 'Bruce Lee', 'Courage', '["mindset", "defeat", "resolve"]', 'emerald', 0, 124),
('quote-1061', 'Knowing is not enough, we must apply. Willing is not enough, we must do.', 'Bruce Lee', 'Courage', '["action", "application", "deeds"]', 'midnight', 0, 51),
('quote-1062', 'I fear not the man who has practiced 10,000 kicks once, but I fear the man who has practiced one kick 10,000 times.', 'Bruce Lee', 'Courage', '["mastery", "focus", "repetition"]', 'nordic', 0, 116),
('quote-1063', 'Mistakes are always forgivable, if one has the courage to admit them.', 'Bruce Lee', 'Courage', '["humility", "courage", "forgiveness"]', 'sunset', 0, 131),
('quote-1064', 'The successful warrior is the average man, with laser-like focus.', 'Bruce Lee', 'Courage', '["focus", "warrior", "simplicity"]', 'light', 0, 97),
('quote-1065', 'Always be yourself, express yourself, have faith in yourself, do not go out and look for a successful personality and duplicate it.', 'Bruce Lee', 'Courage', '["authenticity", "self-faith", "originality"]', 'emerald', 0, 48),
('quote-1066', 'Adapt what is useful, reject what is useless, and add what is specifically your own.', 'Bruce Lee', 'Courage', '["synthesis", "adaptability", "ownership"]', 'midnight', 0, 36),
('quote-1067', 'Notice that the stiffest tree is most easily cracked, while the bamboo or willow survives by bending with the wind.', 'Bruce Lee', 'Courage', '["flexibility", "willow", "survival"]', 'nordic', 0, 108),
('quote-1068', 'If you spend too much time thinking about a thing, you''ll never get it done.', 'Bruce Lee', 'Courage', '["action", "momentum", "overthinking"]', 'sunset', 0, 71),
('quote-1069', 'Choose the positive. You have choice, you are master of your attitude, choose the positive, the constructive.', 'Bruce Lee', 'Courage', '["attitude", "mastery", "positivity"]', 'light', 0, 95),
('quote-1070', 'To hell with circumstances; I create opportunities.', 'Bruce Lee', 'Courage', '["creation", "opportunities", "sovereignty"]', 'emerald', 0, 96),
('quote-1071', 'Real living is living for others.', 'Bruce Lee', 'Courage', '["service", "living", "generosity"]', 'midnight', 0, 91)
